package main

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
)

// Rule is a literal find/replace applied to every string in the transcript.
type Rule struct{ Find, Replace string }

// Scrubber removes personal data from transcript strings and checks the result for leaks.
// Private terms (home dir, username, project names) are never hard-coded: they come from
// the running machine and from a gitignored rules file.
type Scrubber struct {
	rules []Rule
}

var (
	emailRe = regexp.MustCompile(`[A-Za-z0-9._%+-]+@([A-Za-z0-9-]+\.)+[A-Za-z]{2,}`)
	// The app attaches a list of recently used folders on this machine; none of it belongs in the export.
	recentFoldersRe = regexp.MustCompile(`(?s)<recent-project-folders>[removed]</recent-project-folders>`)

	// Domains that are safe to keep (commit trailers, docs examples).
	keepEmailDomains = []string{"anthropic.com", "example.com", "example.org", "users.noreply.github.com"}

	// Credential-shaped strings. A hit fails the export; values are never printed.
	secretPatterns = map[string]*regexp.Regexp{
		"anthropic key":   regexp.MustCompile(`sk-ant-[A-Za-z0-9_-]{10,}`),
		"openai-style key": regexp.MustCompile(`\bsk-[A-Za-z0-9]{20,}`),
		"google api key":  regexp.MustCompile(`AIza[0-9A-Za-z_-]{30,}`),
		"aws access key":  regexp.MustCompile(`AKIA[0-9A-Z]{16}`),
		"github token":    regexp.MustCompile(`gh[pousr]_[A-Za-z0-9]{30,}`),
		"stripe key":      regexp.MustCompile(`(?:sk|rk)_(?:live|test)_[A-Za-z0-9]{10,}`),
		"jwt":             regexp.MustCompile(`eyJ[A-Za-z0-9_-]{15,}\.eyJ[A-Za-z0-9_-]{10,}`),
		"private key":     regexp.MustCompile(`-----BEGIN [A-Z ]*PRIVATE KEY`),
	}
)

// NewScrubber builds a scrubber. home and username come from the current machine; extra
// rules come from the rules file. Longer finds are applied first so specific rules win.
func NewScrubber(home, username string, extra []Rule) *Scrubber {
	var rules []Rule
	if home != "" && home != "/" {
		rules = append(rules, Rule{home, "~"})
	}
	if len(username) >= 4 { // shorter names would mangle ordinary words
		rules = append(rules, Rule{username, "<user>"})
	}
	sort.SliceStable(extra, func(i, j int) bool { return len(extra[i].Find) > len(extra[j].Find) })
	rules = append(rules, extra...)
	return &Scrubber{rules: rules}
}

// String scrubs one string. Order matters: emails go before the username rule so
// "name@host" is still recognisable as an email when it is replaced.
func (s *Scrubber) String(in string) string {
	out := recentFoldersRe.ReplaceAllString(in, "<recent-project-folders>[removed]</recent-project-folders>")
	out = emailRe.ReplaceAllStringFunc(out, func(m string) string {
		if keepEmail(m) {
			return m
		}
		return "<email>"
	})
	for _, r := range s.rules {
		out = strings.ReplaceAll(out, r.Find, r.Replace)
	}
	return out
}

// Value scrubs every string inside a decoded JSON value.
func (s *Scrubber) Value(v any) any {
	switch t := v.(type) {
	case string:
		return s.String(t)
	case []any:
		for i := range t {
			t[i] = s.Value(t[i])
		}
		return t
	case map[string]any:
		for k := range t {
			t[k] = s.Value(t[k])
		}
		return t
	default:
		return v
	}
}

// Leak is one suspicious match in the scrubbed output. It names the kind and line only.
type Leak struct {
	Kind string
	Line int
}

func (l Leak) String() string { return fmt.Sprintf("line %d: %s", l.Line, l.Kind) }

// Leaks scans scrubbed text for anything that should not have survived: credential
// patterns, foreign emails, and any rule's find text in any letter case.
func (s *Scrubber) Leaks(text string) []Leak {
	var leaks []Leak
	for i, line := range strings.Split(text, "\n") {
		n := i + 1
		for kind, re := range secretPatterns {
			if re.MatchString(line) {
				leaks = append(leaks, Leak{kind, n})
			}
		}
		for _, m := range emailRe.FindAllString(line, -1) {
			if !keepEmail(m) {
				leaks = append(leaks, Leak{"email address", n})
			}
		}
		lower := strings.ToLower(line)
		for i, r := range s.rules {
			if strings.Contains(lower, strings.ToLower(r.Find)) {
				leaks = append(leaks, Leak{fmt.Sprintf("scrub rule #%d text", i+1), n})
			}
		}
	}
	sort.Slice(leaks, func(i, j int) bool { return leaks[i].Line < leaks[j].Line })
	return leaks
}

func keepEmail(addr string) bool {
	lower := strings.ToLower(addr)
	for _, d := range keepEmailDomains {
		if strings.HasSuffix(lower, "@"+d) || strings.HasSuffix(lower, "."+d) {
			return true
		}
	}
	return false
}

// LoadRules reads "find => replace" lines; blank lines and # comments are skipped.
// A missing file is not an error.
func LoadRules(path string) ([]Rule, error) {
	f, err := os.Open(path)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var rules []Rule
	sc := bufio.NewScanner(f)
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		find, repl, ok := strings.Cut(line, "=>")
		find, repl = strings.TrimSpace(find), strings.TrimSpace(repl)
		if !ok || find == "" {
			return nil, fmt.Errorf("%s:%d: want \"find => replace\"", path, n)
		}
		rules = append(rules, Rule{find, repl})
	}
	return rules, sc.Err()
}

package main

import (
	"archive/zip"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"path"
	"strings"
)

// Row is one kept transcript entry, reduced to what a reader needs.
type Row map[string]any

// ReadTranscript returns the rows of transcript.jsonl from a Claude app session export.
// Subagent transcripts, metadata and app state in the zip are deliberately ignored.
func ReadTranscript(zipPath string) ([]map[string]any, error) {
	zr, err := zip.OpenReader(zipPath)
	if err != nil {
		return nil, err
	}
	defer zr.Close()

	for _, f := range zr.File {
		if path.Clean(f.Name) != "transcript.jsonl" {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return nil, err
		}
		defer rc.Close()
		return decodeRows(rc)
	}
	return nil, errors.New("transcript.jsonl not found at the root of the zip")
}

func decodeRows(r io.Reader) ([]map[string]any, error) {
	dec := json.NewDecoder(r) // streams; some lines are megabytes long
	var rows []map[string]any
	for {
		var row map[string]any
		err := dec.Decode(&row)
		if errors.Is(err, io.EOF) {
			return rows, nil
		}
		if err != nil {
			return nil, fmt.Errorf("row %d: %w", len(rows)+1, err)
		}
		rows = append(rows, row)
	}
}

// Prune keeps only conversation rows (user and assistant) and only the fields that carry
// the conversation. App bookkeeping (request blobs, attachments, permission state,
// thinking signatures) is dropped.
func Prune(rows []map[string]any) []Row {
	var out []Row
	for _, r := range rows {
		typ, _ := r["type"].(string)
		if typ != "user" && typ != "assistant" {
			continue
		}
		msg, _ := r["message"].(map[string]any)
		if msg == nil {
			continue
		}
		kept := Row{
			"type":      typ,
			"uuid":      r["uuid"],
			"timestamp": r["timestamp"],
			"message":   map[string]any{"role": msg["role"], "content": pruneContent(msg["content"])},
		}
		if p, ok := r["parentUuid"]; ok {
			kept["parentUuid"] = p
		}
		if meta, _ := r["isMeta"].(bool); meta {
			kept["isMeta"] = true
		}
		out = append(out, kept)
	}
	return out
}

func pruneContent(c any) any {
	blocks, ok := c.([]any)
	if !ok {
		return c // plain string
	}
	out := make([]any, 0, len(blocks))
	for _, b := range blocks {
		m, ok := b.(map[string]any)
		if !ok {
			continue
		}
		switch m["type"] {
		case "thinking":
			out = append(out, map[string]any{"type": "thinking", "thinking": m["thinking"]})
		case "redacted_thinking":
			// opaque, nothing a reader can use
		case "tool_use":
			out = append(out, map[string]any{"type": "tool_use", "id": m["id"], "name": m["name"], "input": m["input"]})
		case "tool_result":
			out = append(out, map[string]any{
				"type": "tool_result", "tool_use_id": m["tool_use_id"],
				"is_error": m["is_error"], "content": pruneContent(m["content"]),
			})
		case "image":
			out = append(out, map[string]any{"type": "text", "text": "[image omitted]"})
		default:
			out = append(out, m)
		}
	}
	return out
}

// EncodeJSONL writes rows one per line.
func EncodeJSONL(rows []Row) ([]byte, error) {
	var b strings.Builder
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	for _, r := range rows {
		if err := enc.Encode(r); err != nil {
			return nil, err
		}
	}
	return []byte(b.String()), nil
}

package main

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	maxToolInput  = 4000
	maxToolResult = 3000
)

// App-injected context in user turns; useful in the raw JSONL, noise in the readable view.
var reminderRe = regexp.MustCompile(`(?s)<system-reminder>.*?</system-reminder>`)

// RenderMarkdown turns pruned, scrubbed rows into a readable conversation.
// The JSONL next to it stays the complete record; this view truncates long tool I/O.
func RenderMarkdown(title string, rows []Row) string {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", title)
	b.WriteString("Scrubbed export of a Claude Code session. Tool inputs and outputs are truncated here; the `.jsonl` file next to this one has them in full.\n")

	speaker := ""
	heading := func(who string, row Row) {
		if who == speaker {
			return
		}
		speaker = who
		fmt.Fprintf(&b, "\n---\n\n## %s%s\n\n", who, stamp(row))
	}

	for _, row := range rows {
		if row["isMeta"] == true {
			continue
		}
		msg, _ := row["message"].(map[string]any)
		switch c := msg["content"].(type) {
		case string:
			if text := cleanUserText(c); text != "" {
				heading(who(row), row)
				b.WriteString(text + "\n\n")
			}
		case []any:
			for _, raw := range c {
				blk, _ := raw.(map[string]any)
				switch blk["type"] {
				case "text":
					text, _ := blk["text"].(string)
					if row["type"] == "user" {
						text = cleanUserText(text)
					}
					if strings.TrimSpace(text) != "" {
						heading(who(row), row)
						b.WriteString(strings.TrimSpace(text) + "\n\n")
					}
				case "thinking":
					if t, _ := blk["thinking"].(string); strings.TrimSpace(t) != "" {
						heading("Claude", row)
						details(&b, "Thinking", "text", t, 0)
					}
				case "tool_use":
					heading("Claude", row)
					name, _ := blk["name"].(string)
					in, _ := blk["input"].(map[string]any)
					label := "Tool: " + name
					if d, _ := in["description"].(string); d != "" {
						label += " — " + d
					}
					js, _ := json.MarshalIndent(in, "", "  ")
					details(&b, label, "json", string(js), maxToolInput)
				case "tool_result":
					label := "Result"
					if blk["is_error"] == true {
						label = "Result (error)"
					}
					details(&b, label, "text", resultText(blk["content"]), maxToolResult)
				}
			}
		}
	}
	return b.String()
}

func who(row Row) string {
	if row["type"] == "assistant" {
		return "Claude"
	}
	return "User"
}

func stamp(row Row) string {
	ts, _ := row["timestamp"].(string)
	t, err := time.Parse(time.RFC3339Nano, ts)
	if err != nil {
		return ""
	}
	return " · " + t.UTC().Format("2006-01-02 15:04 UTC")
}

func cleanUserText(s string) string {
	return strings.TrimSpace(reminderRe.ReplaceAllString(s, ""))
}

func resultText(c any) string {
	switch t := c.(type) {
	case string:
		return t
	case []any:
		var parts []string
		for _, raw := range t {
			if m, ok := raw.(map[string]any); ok {
				if s, ok := m["text"].(string); ok {
					parts = append(parts, s)
				}
			}
		}
		return strings.Join(parts, "\n")
	}
	return ""
}

// details writes a collapsed block. limit 0 means no truncation.
func details(b *strings.Builder, summary, lang, body string, limit int) {
	body = strings.TrimRight(body, "\n")
	if limit > 0 && utf8.RuneCountInString(body) > limit {
		total := utf8.RuneCountInString(body)
		body = string([]rune(body)[:limit]) + fmt.Sprintf("\n… [truncated: %d of %d characters shown]", limit, total)
	}
	fence := fenceFor(body)
	fmt.Fprintf(b, "<details><summary>%s</summary>\n\n%s%s\n%s\n%s\n\n</details>\n\n",
		escapeHTML(summary), fence, lang, body, fence)
}

// fenceFor returns a backtick fence longer than any backtick run inside body.
func fenceFor(body string) string {
	longest, run := 0, 0
	for _, r := range body {
		if r == '`' {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", max(3, longest+1))
}

func escapeHTML(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
}

// Command sessionexport turns a Claude app session export (zip) into a scrubbed
// transcript for ai-sessions/: a full .jsonl record and a readable .md view.
//
//	go run ./tools/sessionexport -in ~/Downloads/session-export-123.zip -name 01-scaffold
//
// Personal data is removed with machine-derived rules (home dir, username), an email
// filter, and extra "find => replace" rules from a gitignored file (default .scrub.local).
// The export fails, writing nothing, if anything credential-shaped or private survives.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"os/user"
	"path/filepath"
	"time"
)

func main() {
	in := flag.String("in", "", "session export zip from the Claude app (required)")
	out := flag.String("out", "ai-sessions", "output directory")
	name := flag.String("name", "", "base file name, e.g. 01-scaffold (default: date of the session)")
	rulesPath := flag.String("rules", ".scrub.local", "extra scrub rules file, one \"find => replace\" per line")
	flag.Parse()

	if *in == "" {
		flag.Usage()
		os.Exit(2)
	}
	if err := run(*in, *out, *name, *rulesPath); err != nil {
		fmt.Fprintln(os.Stderr, "sessionexport:", err)
		os.Exit(1)
	}
}

func run(in, outDir, name, rulesPath string) error {
	extra, err := LoadRules(rulesPath)
	if err != nil {
		return err
	}
	home, _ := os.UserHomeDir()
	username := ""
	if u, err := user.Current(); err == nil {
		username = u.Username
	}
	s := NewScrubber(home, username, extra)

	raw, err := ReadTranscript(in)
	if err != nil {
		return err
	}
	rows := Prune(raw)
	if len(rows) == 0 {
		return errors.New("no conversation rows in the transcript")
	}
	for _, r := range rows {
		s.Value(map[string]any(r))
	}

	if name == "" {
		name = sessionDate(rows) + "-session"
	}
	jsonl, err := EncodeJSONL(rows)
	if err != nil {
		return err
	}
	md := RenderMarkdown("Session "+name, rows)

	if leaks := append(tag("jsonl", s.Leaks(string(jsonl))), tag("md", s.Leaks(md))...); len(leaks) > 0 {
		for _, l := range leaks {
			fmt.Fprintln(os.Stderr, "  leak:", l)
		}
		return fmt.Errorf("%d possible leaks; add rules to %s and run again (nothing was written)", len(leaks), rulesPath)
	}

	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return err
	}
	jsonlPath := filepath.Join(outDir, name+".jsonl")
	mdPath := filepath.Join(outDir, name+".md")
	if err := os.WriteFile(jsonlPath, jsonl, 0o644); err != nil {
		return err
	}
	if err := os.WriteFile(mdPath, []byte(md), 0o644); err != nil {
		return err
	}
	fmt.Printf("wrote %s (%d rows) and %s\n", jsonlPath, len(rows), mdPath)
	return nil
}

func sessionDate(rows []Row) string {
	for _, r := range rows {
		if ts, ok := r["timestamp"].(string); ok {
			if t, err := time.Parse(time.RFC3339Nano, ts); err == nil {
				return t.UTC().Format("2006-01-02")
			}
		}
	}
	return time.Now().UTC().Format("2006-01-02")
}

type fileLeak struct {
	file string
	Leak
}

func (l fileLeak) String() string { return l.file + " " + l.Leak.String() }

func tag(file string, leaks []Leak) []fmt.Stringer {
	out := make([]fmt.Stringer, len(leaks))
	for i, l := range leaks {
		out[i] = fileLeak{file, l}
	}
	return out
}

