func writeZip(t *testing.T, files map[string]string) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "export.zip")
	f, err := os.Create(p)
	if err != nil {
		t.Fatal(err)
	}
	zw := zip.NewWriter(f)
	for name, body := range files {
		w, _ := zw.Create(name)
		w.Write([]byte(body))
	}
	zw.Close()
	f.Close()
	return p
}

func TestPipeline(t *testing.T) {
	zipPath := writeZip(t, map[string]string{
		"transcript.jsonl":              fixture,
		"metadata.json":                 `{"secret":"x"}`,
		"sess/subagents/agent-1.jsonl": `{"type":"user"}`,
	})
	raw, err := ReadTranscript(zipPath)
	if err != nil {
		t.Fatal(err)
	}
	rows := Prune(raw)
	if len(rows) != 4 {
		t.Fatalf("kept %d rows, want 4 (user/assistant only)", len(rows))
	}
	s := testScrubber()
	for _, r := range rows {
		s.Value(map[string]any(r))
	}
	jsonl, err := EncodeJSONL(rows)
	if err != nil {
		t.Fatal(err)
	}
	md := RenderMarkdown("Session test", rows)

	for _, out := range []string{string(jsonl), md} {
		for _, bad := range []string{"alice", "secret-proj", "SIG", "huge internal payload", `"caller"`} {
			if strings.Contains(out, bad) {
