51	func startEmbedded(dataDir string, log *slog.Logger) (string, func(), error) {
52		base, err := filepath.Abs(filepath.Join(dataDir, "pg"))
53		if err != nil {
54			return "", nil, err
55		}
56		if err := os.MkdirAll(base, 0o700); err != nil {
57			return "", nil, err
58		}
59		password, err := embeddedPassword(filepath.Join(base, "password"))
60		if err != nil {
61			return "", nil, err
62		}
63		logFile, err := os.OpenFile(filepath.Join(base, "postgres.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
64		if err != nil {
65			return "", nil, err
66		}
67	
68		pg := embeddedpostgres.NewDatabase(embeddedpostgres.DefaultConfig().
69			Version(embeddedpostgres.V17).
70			Port(EmbeddedPort).
71			Username("agents").
72			Password(password).
73			Database("agents").
74			DataPath(filepath.Join(base, "data")).
75			RuntimePath(filepath.Join(base, "runtime")).
76			BinariesPath(filepath.Join(base, "bin")).
77			StartTimeout(2 * time.Minute).
78			Logger(logFile))
79	
80		log.Info("starting embedded PostgreSQL; the first run downloads it once", "dir", base, "port", EmbeddedPort)
81		if err := pg.Start(); err != nil {
82			logFile.Close()
83			return "", nil, fmt.Errorf("start embedded postgres (log: %s): %w", logFile.Name(), err)
84		}
85		stop := func() {
86			if err := pg.Stop(); err != nil {
87				log.Error("stop embedded postgres", "error", err)
88			}
89			logFile.Close()
90		}
91		url := fmt.Sprintf("postgres://agents:%s@localhost:%d/agents?sslmode=disable", password, EmbeddedPort)
92		return url, stop, nil
