95	// embeddedPassword returns the password of the embedded database, creating a
96	// random one on first use. Keeping it in the data directory means no password
97	// lives in the code or in git.
98	func embeddedPassword(path string) (string, error) {
99		b, err := os.ReadFile(path)
100		if err == nil {
101			return strings.TrimSpace(string(b)), nil
102		}
103		if !errors.Is(err, os.ErrNotExist) {
104			return "", err
105		}
106		raw := make([]byte, 16)
107		if _, err := rand.Read(raw); err != nil {
108			return "", err
109		}
110		pw := hex.EncodeToString(raw)
111		if err := os.WriteFile(path, []byte(pw), 0o600); err != nil {
112			return "", err
113		}
114		return pw, nil
115	}
