16		// DatabaseURL points at PostgreSQL. When empty, the server starts an
17		// embedded PostgreSQL under DataDir.
18		DatabaseURL string
19		DataDir     string
20		// MasterKey encrypts users' model keys and team secrets at rest.
21		MasterKey []byte
22		// SeedUserPassword is the password of the predefined demo users.
23		SeedUserPassword string
24		// WebDir holds the static Next.js build served at "/".
25		WebDir string
26		// CookieSecure marks the session cookie Secure. Enable behind HTTPS.
27		CookieSecure bool
28		// AllowPrivateTools lets tools call loopback and private addresses. Off
29		// by default; useful only for local tool servers in development.
30		AllowPrivateTools bool
31		// LogJSON switches logs to JSON, for log collectors in a cluster.
32		LogJSON bool
33		// SandboxImage is the Docker image coding agents run in.
34		SandboxImage string
35		// SandboxGatewayURL is the model gateway as a sandbox reaches it.
36		SandboxGatewayURL string
37		// PublicURL is where browsers reach the server (OAuth redirects).
38		PublicURL string
39		// GitHub OAuth App for "Connect GitHub"; optional.
40		GitHubOAuthClientID     string
41		GitHubOAuthClientSecret string
42	}
43	
44	// keys lists the only variables the server reads. Anything else in .env
45	// (for example the model keys used by scripts/) is ignored on purpose.
46	var keys = []string{
47		"PORT", "DATABASE_URL", "DATA_DIR", "PLATFORM_MASTER_KEY",
48		"SEED_USER_PASSWORD", "WEB_DIR", "COOKIE_SECURE", "ALLOW_PRIVATE_TOOL_HOSTS", "LOG_FORMAT",
49		"SANDBOX_IMAGE", "SANDBOX_GATEWAY_URL",
50		"PUBLIC_URL", "GITHUB_OAUTH_CLIENT_ID", "GITHUB_OAUTH_CLIENT_SECRET",
51	}
52	
53	// Load reads settings from the process environment. Values from envFile are
54	// used only for variables that are not already set in the environment.
55	func Load(envFile string) (Config, error) {
56		fileVals, err := readEnvFile(envFile)
57		if err != nil {
58			return Config{}, err
59		}
60		get := func(key, def string) string {
61			if v, ok := os.LookupEnv(key); ok {
62				return v
63			}
64			if v, ok := fileVals[key]; ok {
65				return v
66			}
67			return def
68		}
69	
70		cfg := Config{
71			Port:              get("PORT", "8080"),
72			DatabaseURL:       get("DATABASE_URL", ""),
73			DataDir:           get("DATA_DIR", ".data"),
74			SeedUserPassword:  get("SEED_USER_PASSWORD", ""),
75			WebDir:            get("WEB_DIR", "web/out"),
76			CookieSecure:      get("COOKIE_SECURE", "false") == "true",
77			AllowPrivateTools: get("ALLOW_PRIVATE_TOOL_HOSTS", "false") == "true",
78			LogJSON:           get("LOG_FORMAT", "text") == "json",
79			SandboxImage:      get("SANDBOX_IMAGE", "agents-platform-sandbox:local"),
80		}
81		cfg.SandboxGatewayURL = get("SANDBOX_GATEWAY_URL", "http://host.docker.internal:"+cfg.Port+"/gateway/v1")
82		cfg.PublicURL = get("PUBLIC_URL", "http://localhost:"+cfg.Port)
83		cfg.GitHubOAuthClientID = get("GITHUB_OAUTH_CLIENT_ID", "")
84		cfg.GitHubOAuthClientSecret = get("GITHUB_OAUTH_CLIENT_SECRET", "")
85	
86		rawKey := get("PLATFORM_MASTER_KEY", "")
87		if rawKey == "" {
88			return Config{}, errors.New("PLATFORM_MASTER_KEY is not set (generate one with: openssl rand -base64 32)")
89		}
90		cfg.MasterKey, err = base64.StdEncoding.DecodeString(rawKey)
91		if err != nil || len(cfg.MasterKey) != 32 {
92			return Config{}, errors.New("PLATFORM_MASTER_KEY must be 32 bytes, base64 encoded")
93		}
94		if cfg.SeedUserPassword == "" {
95			return Config{}, errors.New("SEED_USER_PASSWORD is not set")
96		}
97		return cfg, nil
98	}
99	
100	// readEnvFile parses KEY=VALUE lines, keeping only the keys the server uses.
101	// A missing file is not an error.
102	func readEnvFile(path string) (map[string]string, error) {
103		vals := map[string]string{}
104		if path == "" {
105			return vals, nil
106		}
107		f, err := os.Open(path)
108		if errors.Is(err, os.ErrNotExist) {
109			return vals, nil
110		}
111		if err != nil {
112			return nil, fmt.Errorf("open %s: %w", path, err)
113		}
114		defer f.Close()
115	
116		wanted := map[string]bool{}
117		for _, k := range keys {
118			wanted[k] = true
119		}
120		sc := bufio.NewScanner(f)
121		for sc.Scan() {
122			line := strings.TrimSpace(sc.Text())
123			if line == "" || strings.HasPrefix(line, "#") {
124				continue
125			}
126			k, v, ok := strings.Cut(line, "=")
127			if !ok {
128				continue
129			}
130			k = strings.TrimSpace(strings.TrimPrefix(k, "export "))
131			if !wanted[k] {
132				continue
133			}
134			v = envValue(v)
135			if strings.Contains(v, "$(") {
136				return nil, fmt.Errorf("%s in %s is a shell command, but the file is not run by a shell: put the command's output there", k, path)
137			}
138			vals[k] = v
139		}
140		return vals, sc.Err()
141	}
142	
143	// envValue reads a value as a shell would: "quoted" or 'quoted' values are
144	// taken as they are, and an unquoted value ends at " #" (a comment).
145	func envValue(v string) string {
146		v = strings.TrimSpace(v)
147		if len(v) >= 2 && (v[0] == '"' || v[0] == '\'') {
148			if end := strings.IndexByte(v[1:], v[0]); end >= 0 {
149				return v[1 : 1+end]
150			}
151		}
152		for i := 1; i < len(v); i++ {
153			if v[i] == '#' && (v[i-1] == ' ' || v[i-1] == '\t') {
154				return strings.TrimSpace(v[:i])
155			}
156		}
157		return v
158	}
