1	// Package llmtest provides a scripted model provider for tests.
2	package llmtest
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8		"sync"
9	
10		"github.com/m<user>/agents-platform/internal/llm"
11	)
12	
13	// Step produces one model response.
14	type Step func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error)
15	
16	// Fake returns its steps in order, one per Generate call, and records what it
17	// was asked.
18	type Fake struct {
19		name string
20		mu   sync.Mutex
21		// steps are consumed in order.
22		steps    []Step
23		requests []llm.Request
24		keys     []string
25	}
26	
27	func New(name string, steps ...Step) *Fake {
28		return &Fake{name: name, steps: steps}
29	}
30	
31	func (f *Fake) Name() string { return f.name }
32	
33	// Script replaces the remaining steps.
34	func (f *Fake) Script(steps ...Step) {
35		f.mu.Lock()
36		defer f.mu.Unlock()
37		f.steps = steps
38	}
39	
40	func (f *Fake) Generate(ctx context.Context, apiKey string, req llm.Request, onText func(string)) (llm.Response, error) {
41		f.mu.Lock()
42		f.requests = append(f.requests, req)
43		f.keys = append(f.keys, apiKey)
44		if len(f.steps) == 0 {
45			f.mu.Unlock()
46			return llm.Response{}, errors.New("fake provider: no scripted response left")
47		}
48		step := f.steps[0]
49		f.steps = f.steps[1:]
50		f.mu.Unlock()
51		return step(ctx, req, onText)
52	}
53	
54	// Requests returns copies of the requests received so far.
55	func (f *Fake) Requests() []llm.Request {
56		f.mu.Lock()
57		defer f.mu.Unlock()
58		return append([]llm.Request(nil), f.requests...)
59	}
60	
61	// Keys returns the API keys the calls were made with.
62	func (f *Fake) Keys() []string {
63		f.mu.Lock()
64		defer f.mu.Unlock()
65		return append([]string(nil), f.keys...)
66	}
67	
68	var usage = llm.Usage{InputTokens: 100, OutputTokens: 20}
69	
70	// Text answers with text, streamed in two pieces.
71	func Text(s string) Step {
72		return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
73			if onText != nil && len(s) > 1 {
74				onText(s[:len(s)/2])
75				onText(s[len(s)/2:])
76			}
77			return llm.Response{Message: llm.Message{Role: llm.RoleAssistant, Text: s}, Usage: usage}, nil
78		}
79	}
80	
81	// Calls asks for tool calls. Each pair is a tool name and its raw arguments.
82	func Calls(nameArgs ...string) Step {
83		return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
84			msg := llm.Message{Role: llm.RoleAssistant}
85			for i := 0; i+1 < len(nameArgs); i += 2 {
86				msg.ToolCalls = append(msg.ToolCalls, llm.ToolCall{
87					ID: fmt.Sprintf("call_%d_%d", len(req.Messages), i/2), Name: nameArgs[i], Arguments: nameArgs[i+1],
88				})
89			}
90			return llm.Response{Message: msg, Usage: usage}, nil
91		}
92	}
93	
94	// Fail returns err.
95	func Fail(err error) Step {
96		return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
97			return llm.Response{}, err
98		}
99	}
100	
101	// Malformed reports a tool call the provider could not parse.
102	func Malformed() Step {
103		return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
104			return llm.Response{Message: llm.Message{Role: llm.RoleAssistant}, Malformed: true, Usage: usage}, nil
105		}
106	}
107	
108	// Wait blocks until release is closed or the call is cancelled, then runs next.
109	func Wait(release <-chan struct{}, next Step) Step {
110		return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
111			select {
112			case <-release:
113				return next(ctx, req, onText)
114			case <-ctx.Done():
115				return llm.Response{}, context.Cause(ctx)
116			}
117		}
118	}
