508	// executeOnce runs one segment of a run: from claiming it until it ends,
509	// pauses or is handed back to the queue. It reports whether to continue the
510	// run at once; by then its own deferred cleanup has finished.
511	func (r *Runner) executeOnce(runID string) (again bool) {
512		bg := context.Background()
513		run, err := r.st.ClaimRun(bg, runID, r.name, r.cfg.LeaseTTL)
514		if errors.Is(err, store.ErrNotFound) {
515			return // not queued any more: another replica has it, or it ended
516		}
517		if err != nil {
518			r.log.Error("claim run", "run", runID, "error", err)
519			return
520		}
521		log := r.log.With("run", runID)
522	
523		ctx, cancel := context.WithCancelCause(bg)
524		defer cancel(nil)
525		r.mu.Lock()
526		r.active[runID] = cancel
527		r.mu.Unlock()
528		defer func() {
529			r.mu.Lock()
530			delete(r.active, runID)
531			r.mu.Unlock()
532		}()
533		if run.CancelRequested {
534			cancel(errCancelled)
535		}
536		// The lease is renewed until this function returns, not only until ctx
537		// is cancelled: cleaning up after a cancel (stopping a sandbox) can take
538		// longer than the lease, and the run must not be mistaken for lost.
539		hbCtx, stopHeartbeat := context.WithCancel(bg)
540		defer stopHeartbeat()
541		go r.heartbeat(hbCtx, runID, cancel)
542		timeout := r.cfg.Limits.timeout(run)
543		ctx, stopTimer := context.WithTimeoutCause(ctx, timeout, errTimeout)
544		defer stopTimer()
545	
546		output, err := r.runSegment(ctx, run)
547		// A cancel or timeout can surface as a database error ("context
548		// canceled") from whatever call was in flight; the cause says why.
549		if cause := context.Cause(ctx); err != nil && cause != nil && !errors.Is(err, errPaused) {
550			err = cause
551		}
552	
553		finish := func(status, output, errMsg string) {
554			ok, ferr := r.st.FinishRun(bg, runID, r.name, status, output, errMsg,
555				runFinished{Status: status, Output: output, Error: errMsg})
556			if ferr != nil {
557				log.Error("finish run", "error", ferr)
558			} else if !ok {
559				log.Warn("run was no longer leased by this process when it finished", "status", status)
560			}
561		}
562		if run.ParentRunID != nil {
563			// A finished child queued its waiting parent; continue it here.
564			defer r.Resume(*run.ParentRunID)
565		}
566		switch {
567		case err == nil:
568			finish(store.StatusSucceeded, output, "")
569		case errors.Is(err, errResume):
570			again = true
571		case errors.Is(err, errPaused):
572			log.Info("run paused")
573		case errors.Is(err, errShutdown):
574			r.emit(runID, "requeued", map[string]string{"reason": "the server is shutting down; another server continues this run"})
575			if err := r.st.RequeueRun(bg, runID, r.name); err != nil {
576				log.Error("requeue run", "error", err)
577			}
578		case errors.Is(err, store.ErrLeaseLost):
579			log.Warn("run lease lost; another process has failed or taken over the run")
580		case errors.Is(err, errCancelled):
581			finish(store.StatusCancelled, "", errCancelled.Error())
582		case errors.Is(err, errTimeout):
583			finish(store.StatusFailed, "", fmt.Sprintf("the run took longer than %s", timeout))
584		default:
585			finish(store.StatusFailed, "", err.Error())
586		}
587		return again
588	}
