620				return
621			case <-t.C:
622			}
623			hctx, done := context.WithTimeout(context.Background(), 5*time.Second)
624			cancelRequested, err := r.st.Heartbeat(hctx, runID, r.name, r.cfg.LeaseTTL)
625			done()
626			switch {
627			case errors.Is(err, store.ErrLeaseLost):
628				cancel(store.ErrLeaseLost)
629				return
630			case err != nil:
631				r.log.Warn("heartbeat failed", "run", runID, "error", err)
632			case cancelRequested:
633				cancel(errCancelled)
634			}
635		}
