package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"campaign-composer/internal/store"
)

const maxBodyBytes = 1 << 20 // 1 MiB

type errorBody struct {
	Error struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	var body errorBody
	body.Error.Code = code
	body.Error.Message = message
	writeJSON(w, status, body)
}

// decodeJSON reads a single JSON object into v and rejects unknown fields, so
// typos in a request do not get silently ignored.
func decodeJSON(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	dec.DisallowUnknownFields()
	err := dec.Decode(v)
	if err == nil && !errors.Is(dec.Decode(&struct{}{}), io.EOF) {
		err = errors.New("unexpected data after the object")
	}
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid JSON body: "+err.Error())
		return false
	}
	return true
}

// storeError maps store errors to HTTP responses.
func (s *Server) storeError(w http.ResponseWriter, r *http.Request, err error, what string) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", what+" not found")
	case errors.Is(err, store.ErrConflict):
		writeError(w, http.StatusConflict, "conflict", what+" already exists")
	default:
		s.internalError(w, r, err)
	}
}

// internalError logs an unexpected error and answers 500 without details.
func (s *Server) internalError(w http.ResponseWriter, r *http.Request, err error) {
	s.log.Error("request failed", "method", r.Method, "path", r.URL.Path, "error", err)
	writeError(w, http.StatusInternalServerError, "internal", "internal error")
}

package api

import (
	"net/http"
	"time"
)

// statusRecorder remembers the response status for the access log.
type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (r *statusRecorder) WriteHeader(code int) {
	r.status = code
	r.ResponseWriter.WriteHeader(code)
}

// Unwrap lets http.ResponseController reach the underlying writer, which live
// streams need for flushing.
func (r *statusRecorder) Unwrap() http.ResponseWriter { return r.ResponseWriter }

// logRequests logs method, path, status and duration. It never logs headers or
// bodies, which may carry keys or personal data.
func (s *Server) logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(rec, r)
		s.log.Info("http request",
			"method", r.Method, "path", r.URL.Path, "status", rec.status,
			"duration_ms", time.Since(start).Milliseconds())
	})
}

func (s *Server) recoverPanics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				s.log.Error("panic in handler", "path", r.URL.Path, "panic", v)
				writeError(w, http.StatusInternalServerError, "internal", "internal error")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// Package api is the HTTP layer: routing, middleware and JSON handlers.
package api

import (
	"context"
	"log/slog"
	"net/http"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"campaign-composer/internal/events"
)

type Server struct {
	pool *pgxpool.Pool
	log  *slog.Logger
	hub  *events.Hub

	closing   chan struct{}
	closeOnce sync.Once
}

type Options struct {
	Hub *events.Hub
}

func New(pool *pgxpool.Pool, log *slog.Logger, opts Options) *Server {
	return &Server{pool: pool, log: log, hub: opts.Hub, closing: make(chan struct{})}
}

// CloseStreams ends open event streams. http.Server.Shutdown waits for active
// requests, and a stream would otherwise keep it waiting.
func (s *Server) CloseStreams() {
	s.closeOnce.Do(func() { close(s.closing) })
}

// Handler returns the full HTTP handler with all routes and middleware.
func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /readyz", s.handleReady)

	// Unknown /api paths get a JSON 404.
	mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		writeError(w, http.StatusNotFound, "not_found", "no such endpoint")
	})

	return s.recoverPanics(s.logRequests(mux))
}

func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
	defer cancel()
	if err := s.pool.Ping(ctx); err != nil {
		writeError(w, http.StatusServiceUnavailable, "not_ready", "database unavailable")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
}

// Package backoff computes retry delays: exponential growth with jitter, capped.
// The jitter formula comes from the agents-platform LLM retry; it is shared here so
// LLM calls and message deliveries back off the same way.
package backoff

import (
	"math/rand/v2"
	"time"
)

type Policy struct {
	Base time.Duration // wait before the first retry, before jitter
	Max  time.Duration // cap for any single wait; 0 means no cap
}

// Delay returns how long to wait before retry number attempt (1 = first retry).
// The un-jittered wait doubles each time; the result is uniformly random in
// [wait/2, wait], so many failing jobs do not retry in lockstep.
func (p Policy) Delay(attempt int) time.Duration {
	wait := p.Base
	for i := 1; i < attempt && (p.Max == 0 || wait < p.Max); i++ {
		wait *= 2
	}
	if p.Max > 0 && wait > p.Max {
		wait = p.Max
	}
	if wait <= 0 {
		return 0
	}
	return wait/2 + rand.N(wait/2+1)
}

package backoff

import (
	"testing"
	"time"
)

func TestDelayGrowsWithinJitterAndCap(t *testing.T) {
	p := Policy{Base: time.Second, Max: 10 * time.Second}
	cases := []struct {
		attempt int
		full    time.Duration // un-jittered wait
	}{
		{1, 1 * time.Second},
		{2, 2 * time.Second},
		{3, 4 * time.Second},
		{4, 8 * time.Second},
		{5, 10 * time.Second}, // capped
		{50, 10 * time.Second},
	}
	for _, c := range cases {
		for range 200 {
			d := p.Delay(c.attempt)
			if d < c.full/2 || d > c.full {
				t.Fatalf("attempt %d: delay %s outside [%s, %s]", c.attempt, d, c.full/2, c.full)
			}
		}
	}
}

func TestDelayZeroBase(t *testing.T) {
	if d := (Policy{}).Delay(3); d != 0 {
		t.Fatalf("zero policy delay = %s", d)
	}
}

// Package schema validates JSON documents against a JSON Schema. Ported from the
// agents-platform tool-argument validator.
//
// Claude's structured outputs already guarantee the response's shape, but they
// cannot express constraints such as maxLength or minimum. This package is the
// backend's own check, and its error text is written so it can be sent back to
// the model for a corrected answer.
package schema

import (
	"bytes"
	"errors"
	"fmt"
	"strings"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

type Schema struct {
	compiled *jsonschema.Schema
}

// noLoader refuses every $ref to an external document; the default loader would
// read local files.
type noLoader struct{}

func (noLoader) Load(u string) (any, error) {
	return nil, fmt.Errorf("external schema references are not allowed: %s", u)
}

// Compile compiles an object schema.
func Compile(raw []byte) (*Schema, error) {
	doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
	if err != nil {
		return nil, fmt.Errorf("schema is not valid JSON: %w", err)
	}
	if obj, ok := doc.(map[string]any); !ok || obj["type"] != "object" {
		return nil, errors.New(`schema must be a JSON object with "type": "object"`)
	}
	c := jsonschema.NewCompiler()
	c.UseLoader(noLoader{})
	if err := c.AddResource("schema.json", doc); err != nil {
		return nil, err
	}
	compiled, err := c.Compile("schema.json")
	if err != nil {
		return nil, fmt.Errorf("invalid JSON schema: %w", err)
	}
	return &Schema{compiled}, nil
}

// MustCompile is Compile for schemas embedded in the program.
func MustCompile(raw []byte) *Schema {
	s, err := Compile(raw)
	if err != nil {
		panic(err)
	}
	return s
}

// Parse parses raw JSON and validates it. Numbers keep their exact text
// (json.Number), as the validator needs.
func (s *Schema) Parse(raw string) (map[string]any, error) {
	v, err := jsonschema.UnmarshalJSON(strings.NewReader(raw))
	if err != nil {
		return nil, fmt.Errorf("not valid JSON: %v", err)
	}
	obj, ok := v.(map[string]any)
	if !ok {
		return nil, errors.New("must be a JSON object")
	}
	if err := s.compiled.Validate(obj); err != nil {
		return nil, fmt.Errorf("does not match the schema: %s", describe(err))
	}
	return obj, nil
}

// describe flattens a validation error into "at /path: message" lines, dropping
// the schema URL the library prints first.
func describe(err error) string {
	var ve *jsonschema.ValidationError
	if !errors.As(err, &ve) {
		return err.Error()
	}
	var lines []string
	var walk func(e *jsonschema.ValidationError)
	walk = func(e *jsonschema.ValidationError) {
		if len(e.Causes) == 0 {
			loc := "/" + strings.Join(e.InstanceLocation, "/")
			lines = append(lines, fmt.Sprintf("at %s: %s", loc, e.ErrorKind))
			return
		}
		for _, c := range e.Causes {
			walk(c)
		}
	}
	walk(ve)
	return strings.Join(lines, "; ")
}

package schema

import (
	"strings"
	"testing"
)

const messageSchema = `{
  "type": "object",
  "additionalProperties": false,
  "required": ["sms", "channel"],
  "properties": {
    "sms": {"type": "string", "maxLength": 10},
    "channel": {"enum": ["sms", "email"]},
    "count": {"type": "integer", "minimum": 1}
  }
}`

func TestParseValid(t *testing.T) {
	s := MustCompile([]byte(messageSchema))
	obj, err := s.Parse(`{"sms": "hi there", "channel": "sms", "count": 3}`)
	if err != nil {
		t.Fatal(err)
	}
	if obj["sms"] != "hi there" {
		t.Fatalf("obj = %v", obj)
	}
}

func TestParseErrorsAreReadable(t *testing.T) {
	s := MustCompile([]byte(messageSchema))
	cases := map[string]struct{ in, want string }{
		"too long":      {`{"sms": "much too long", "channel": "sms"}`, "at /sms:"},
		"bad enum":      {`{"sms": "ok", "channel": "fax"}`, "at /channel:"},
		"below minimum": {`{"sms": "ok", "channel": "sms", "count": 0}`, "at /count:"},
		"extra field":   {`{"sms": "ok", "channel": "sms", "sql": "DROP TABLE"}`, "sql"},
		"missing field": {`{"sms": "ok"}`, "channel"},
		"not json":      {`{"sms": `, "not valid JSON"},
		"not an object": {`[1, 2]`, "JSON object"},
	}
	for name, c := range cases {
		_, err := s.Parse(c.in)
		if err == nil {
			t.Errorf("%s: want an error", name)
			continue
		}
		if !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: error %q does not mention %q", name, err, c.want)
		}
		if strings.Contains(err.Error(), "schema.json") {
			t.Errorf("%s: error leaks the schema URL: %q", name, err)
		}
	}
}

func TestCompileRejectsBadSchemas(t *testing.T) {
	for name, raw := range map[string]string{
		"not object type": `{"type": "string"}`,
		"external ref":    `{"type": "object", "properties": {"a": {"$ref": "file:///etc/passwd"}}}`,
		"not json":        `{`,
	} {
		if _, err := Compile([]byte(raw)); err == nil {
			t.Errorf("%s: want an error", name)
		}
	}
}

package events

import (
	"context"
	"encoding/json"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"campaign-composer/internal/store"
)

// Event is one stored entry in a topic's ordered stream.
type Event struct {
	Seq       int64           `json:"seq"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// Add stores an event and rings the topic's doorbell. Run it inside the
// caller's transaction to make the event part of a state change; the NOTIFY is
// then delivered on commit. Taking the next seq locks the topic row, so
// concurrent writers get distinct, gap-free numbers.
func Add(ctx context.Context, db store.DBTX, topic, typ string, data any) (int64, error) {
	b, err := json.Marshal(data)
	if err != nil {
		return 0, err
	}
	var seq int64
	err = db.QueryRow(ctx, `
		WITH s AS (
			INSERT INTO event_topics (topic, last_seq) VALUES ($1, 1)
			ON CONFLICT (topic) DO UPDATE SET last_seq = event_topics.last_seq + 1
			RETURNING last_seq)
		INSERT INTO events (topic, seq, type, data) SELECT $1, last_seq, $2, $3 FROM s
		RETURNING seq`, topic, typ, b).Scan(&seq)
	if err != nil {
		return 0, store.MapErr(err)
	}
	return seq, Ring(ctx, db, topic)
}

// Since returns a topic's events with seq greater than after, oldest first.
func Since(ctx context.Context, db store.DBTX, topic string, after int64) ([]Event, error) {
	rows, err := db.Query(ctx, `
		SELECT seq, type, data, created_at FROM events
		WHERE topic = $1 AND seq > $2 ORDER BY seq`, topic, after)
	if err != nil {
		return nil, store.MapErr(err)
	}
	defer rows.Close()
	out := []Event{}
	for rows.Next() {
		var e Event
		if err := rows.Scan(&e.Seq, &e.Type, &e.Data, &e.CreatedAt); err != nil {
			return nil, store.MapErr(err)
		}
		out = append(out, e)
	}
	return out, store.MapErr(rows.Err())
}

// Ring wakes a topic's listeners without storing anything, e.g. when delivery
// counters changed and streams should re-read them.
func Ring(ctx context.Context, db store.DBTX, topic string) error {
	return notify(ctx, db, topic, "")
}

// maxDelta keeps each NOTIFY payload well under PostgreSQL's 8000-byte limit.
const maxDelta = 2000

// Delta sends streamed text (e.g. model output) to listeners without storing
// it; the complete text is stored as an event when the stream ends. Long text
// is split on UTF-8 boundaries.
func Delta(ctx context.Context, db store.DBTX, topic, text string) error {
	for len(text) > 0 {
		n := min(len(text), maxDelta)
		for n < len(text) && !utf8.RuneStart(text[n]) {
			n--
		}
		if err := notify(ctx, db, topic, text[:n]); err != nil {
			return err
		}
		text = text[n:]
	}
	return nil
}

func notify(ctx context.Context, db store.DBTX, topic, delta string) error {
	payload, _ := json.Marshal(map[string]string{"topic": topic, "delta": delta})
	_, err := db.Exec(ctx, `SELECT pg_notify($1, $2)`, store.NotifyChannel, string(payload))
	return store.MapErr(err)
}

// DeltaBuffer batches streamed text into fewer notifications: it flushes every
// 100 ms or 1 KB. Ported from agents-platform's runner.
type DeltaBuffer struct {
	db    store.DBTX
	topic string

	mu   sync.Mutex
	buf  strings.Builder
	last time.Time
}

func NewDeltaBuffer(db store.DBTX, topic string) *DeltaBuffer {
	return &DeltaBuffer{db: db, topic: topic, last: time.Now()}
}

func (d *DeltaBuffer) Add(s string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.buf.WriteString(s)
	if d.buf.Len() >= 1000 || time.Since(d.last) > 100*time.Millisecond {
		d.flushLocked()
	}
}

// Flush sends whatever is buffered. Call it when the stream ends.
func (d *DeltaBuffer) Flush() {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.flushLocked()
}

func (d *DeltaBuffer) flushLocked() {
	text := d.buf.String()
	d.buf.Reset()
	d.last = time.Now()
	if text == "" {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = Delta(ctx, d.db, d.topic, text) // best effort: the final text is stored anyway
}

// Package events is the live-update layer, ported from agents-platform and
// generalised from runs to topics (e.g. one campaign).
//
// Every event is stored in PostgreSQL first; a NOTIFY on commit is only a
// doorbell. Each server process keeps one LISTEN connection and wakes its local
// subscribers, which then read new events from the database. A missed
// notification only delays an event; it never loses one.
package events

import (
	"context"
	"encoding/json"
	"log/slog"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"campaign-composer/internal/store"
)

// Signal is either a doorbell (Delta empty: re-read the stored state) or a piece
// of streamed text, which is not stored.
type Signal struct {
	Delta string
}

type Subscription struct {
	topic string
	C     <-chan Signal
	c     chan Signal
}

type Hub struct {
	pool *pgxpool.Pool
	log  *slog.Logger

	mu    sync.Mutex
	subs  map[string]map[*Subscription]struct{}
	ready chan struct{}
	once  sync.Once
}

func NewHub(pool *pgxpool.Pool, log *slog.Logger) *Hub {
	return &Hub{pool: pool, log: log, subs: map[string]map[*Subscription]struct{}{}, ready: make(chan struct{})}
}

// Ready is closed once the hub is listening.
func (h *Hub) Ready() <-chan struct{} { return h.ready }

// Subscribe starts delivering signals for one topic. Call Unsubscribe when done.
func (h *Hub) Subscribe(topic string) *Subscription {
	c := make(chan Signal, 256)
	s := &Subscription{topic: topic, C: c, c: c}
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.subs[topic] == nil {
		h.subs[topic] = map[*Subscription]struct{}{}
	}
	h.subs[topic][s] = struct{}{}
	return s
}

func (h *Hub) Unsubscribe(s *Subscription) {
	h.mu.Lock()
	defer h.mu.Unlock()
	delete(h.subs[s.topic], s)
	if len(h.subs[s.topic]) == 0 {
		delete(h.subs, s.topic)
	}
}

// send never blocks: a reader that falls behind loses streamed text, and
// catches up on stored events at its next doorbell or keep-alive.
func (h *Hub) send(topic string, sig Signal) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for s := range h.subs[topic] {
		select {
		case s.c <- sig:
		default:
		}
	}
}

func (h *Hub) ringAll() {
	h.mu.Lock()
	topics := make([]string, 0, len(h.subs))
	for t := range h.subs {
		topics = append(topics, t)
	}
	h.mu.Unlock()
	for _, t := range topics {
		h.send(t, Signal{})
	}
}

// Run listens until ctx is cancelled, reconnecting after errors.
func (h *Hub) Run(ctx context.Context) {
	for {
		err := h.listen(ctx)
		if ctx.Err() != nil {
			return
		}
		h.log.Warn("event listener lost its connection; reconnecting", "error", err)
		select {
		case <-ctx.Done():
			return
		case <-time.After(time.Second):
		}
	}
}

func (h *Hub) listen(ctx context.Context) error {
	pc, err := h.pool.Acquire(ctx)
	if err != nil {
		return err
	}
	// The connection stays in LISTEN mode, so take it out of the pool.
	conn := pc.Hijack()
	defer conn.Close(context.WithoutCancel(ctx))

	if _, err := conn.Exec(ctx, "LISTEN "+store.NotifyChannel); err != nil {
		return err
	}
	h.once.Do(func() { close(h.ready) })
	// Events committed while we were not listening are read on this ring.
	h.ringAll()

	for {
		n, err := conn.WaitForNotification(ctx)
		if err != nil {
			return err
		}
		var p struct {
			Topic string `json:"topic"`
			Delta string `json:"delta"`
		}
		if json.Unmarshal([]byte(n.Payload), &p) != nil || p.Topic == "" {
			continue
		}
		h.send(p.Topic, Signal{Delta: p.Delta})
	}
}

package events_test

import (
	"context"
	"io"
	"log/slog"
	"os"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"campaign-composer/internal/events"
