// Package queue is a PostgreSQL-backed job queue, adapted from the agents-platform
// run lease pattern.
//
//   - Claiming uses FOR UPDATE SKIP LOCKED, so many workers never take the same job.
//   - A claimed job is leased to one worker. Only the lease holder can finish it.
//   - A sweeper requeues jobs whose lease expired (their worker died).
//   - Failures are retried with exponential backoff and jitter, or after the delay
//     the handler asks for (e.g. a provider's Retry-After), until MaxAttempts.
//   - A dedup key makes enqueueing idempotent.
//
// Jobs here are short (one provider call), so the lease is not renewed with a
// heartbeat as agents-platform's long runs are: the handler's context ends
// before the lease does instead.
package queue

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"campaign-composer/internal/events"
	"campaign-composer/internal/store"
)

const (
	StatusQueued    = "queued"
	StatusRunning   = "running"
	StatusSucceeded = "succeeded"
	StatusFailed    = "failed"
)

type Job struct {
	ID          int64           `json:"id"`
	Kind        string          `json:"kind"`
	DedupKey    string          `json:"dedup_key,omitempty"`
	Payload     json.RawMessage `json:"payload"`
	Attempts    int             `json:"attempts"` // including the current one
	MaxAttempts int             `json:"max_attempts"`
	LastError   string          `json:"last_error,omitempty"`
	RunAt       time.Time       `json:"run_at"`
}

type EnqueueOptions struct {
	// DedupKey, if set, makes the enqueue idempotent: a second job with the same
	// key is not created.
	DedupKey    string
	MaxAttempts int       // default 5
	RunAt       time.Time // default now; also how scheduled jobs work
}

// Topic is the event topic that wakes a kind's workers.
func Topic(kind string) string { return "queue:" + kind }

// Enqueue adds a job. Run it in the caller's transaction to make the job part of
// a state change; workers are woken when it commits. created is false when a job
// with the same dedup key already existed.
func Enqueue(ctx context.Context, db store.DBTX, kind string, payload any, opt EnqueueOptions) (id int64, created bool, err error) {
	b, err := json.Marshal(payload)
	if err != nil {
		return 0, false, err
	}
	if opt.MaxAttempts <= 0 {
		opt.MaxAttempts = 5
	}
	var dedup *string
	if opt.DedupKey != "" {
		dedup = &opt.DedupKey
	}
	var runAt *time.Time
	if !opt.RunAt.IsZero() {
		runAt = &opt.RunAt
	}
	err = db.QueryRow(ctx, `
		INSERT INTO jobs (kind, dedup_key, payload, max_attempts, run_at)
		VALUES ($1, $2, $3, $4, coalesce($5, now()))
		ON CONFLICT (dedup_key) DO NOTHING
		RETURNING id`, kind, dedup, b, opt.MaxAttempts, runAt).Scan(&id)
	if errors.Is(store.MapErr(err), store.ErrNotFound) {
		return 0, false, nil // dedup key already taken
	}
	if err != nil {
		return 0, false, store.MapErr(err)
	}
	return id, true, events.Ring(ctx, db, Topic(kind))
}

// permanentError marks a failure that retrying cannot fix.
type permanentError struct{ err error }

func (e *permanentError) Error() string { return e.err.Error() }
func (e *permanentError) Unwrap() error { return e.err }

// Permanent wraps err so the job fails at once instead of being retried.
func Permanent(err error) error { return &permanentError{err} }

type retryAfterError struct {
	err   error
	after time.Duration
}

func (e *retryAfterError) Error() string { return e.err.Error() }
func (e *retryAfterError) Unwrap() error { return e.err }

// RetryAfter wraps err so the next attempt waits d instead of the backoff delay.
func RetryAfter(err error, d time.Duration) error { return &retryAfterError{err, d} }

package queue

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"campaign-composer/internal/backoff"
	"campaign-composer/internal/events"
	"campaign-composer/internal/store"
)

// Handler processes one job. Return nil on success, Permanent(err) for a failure
// retrying cannot fix, RetryAfter(err, d) to wait d before the next attempt, or
// any other error to retry with backoff.
type Handler func(ctx context.Context, job Job) error

// Worker runs a pool of goroutines that claim and process jobs of one kind.
type Worker struct {
	Pool    *pgxpool.Pool
	Hub     *events.Hub // optional: without it, workers only poll
	Log     *slog.Logger
	Kind    string
	Handler Handler
	// OnFailed is called once when a job fails for good (permanent error,
	// attempts used up, or lease expired on the last attempt).
	OnFailed func(ctx context.Context, job Job, err error)

	Concurrency int            // default 4
	LeaseTTL    time.Duration  // default 30s
	PollEvery   time.Duration  // default 1s; doorbells usually wake workers sooner
	SweepEvery  time.Duration  // default 10s
	Backoff     backoff.Policy // default 1s base, 60s cap

	owner string
}

// ErrLeaseExpired is what OnFailed receives for a job whose worker vanished.
var ErrLeaseExpired = errors.New("lease expired: the worker stopped before finishing")

func (w *Worker) setDefaults() {
	if w.Concurrency <= 0 {
		w.Concurrency = 4
	}
	if w.LeaseTTL <= 0 {
		w.LeaseTTL = 30 * time.Second
	}
	if w.PollEvery <= 0 {
		w.PollEvery = time.Second
	}
	if w.SweepEvery <= 0 {
		w.SweepEvery = 10 * time.Second
	}
	if w.Backoff == (backoff.Policy{}) {
		w.Backoff = backoff.Policy{Base: time.Second, Max: time.Minute}
	}
	if w.Log == nil {
		w.Log = slog.Default()
	}
	if w.owner == "" {
		host, _ := os.Hostname()
		b := make([]byte, 4)
		rand.Read(b)
		w.owner = fmt.Sprintf("%s/%d/%s", host, os.Getpid(), hex.EncodeToString(b))
	}
}

// handlerTimeout ends the handler before its lease, so the sweeper never
// requeues a job that is still being worked on.
func (w *Worker) handlerTimeout() time.Duration {
	return max(w.LeaseTTL*4/5, w.LeaseTTL-5*time.Second)
}

// Run processes jobs until ctx is cancelled, then waits for jobs in progress to
// finish (each bounded by the lease).
func (w *Worker) Run(ctx context.Context) {
	w.setDefaults()
	log := w.Log.With("kind", w.Kind)

	wake := make(chan struct{}, w.Concurrency)
	if w.Hub != nil {
		sub := w.Hub.Subscribe(Topic(w.Kind))
		defer w.Hub.Unsubscribe(sub)
		go func() {
			for {
				select {
				case <-ctx.Done():
					return
				case <-sub.C:
					for range w.Concurrency { // wake every idle goroutine
						select {
						case wake <- struct{}{}:
						default:
						}
					}
				}
			}
		}()
	}

	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		t := time.NewTicker(w.SweepEvery)
		defer t.Stop()
		for {
			w.Sweep(ctx)
			select {
			case <-ctx.Done():
				return
			case <-t.C:
			}
		}
	}()

	for range w.Concurrency {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for ctx.Err() == nil {
				job, ok, err := w.claim(ctx)
				if err != nil && ctx.Err() == nil {
					log.Error("claim job", "error", err)
				}
				if !ok {
					select {
					case <-ctx.Done():
					case <-wake:
					case <-time.After(w.PollEvery):
					}
					continue
				}
				w.process(job)
			}
		}()
	}
	wg.Wait()
}

func (w *Worker) claim(ctx context.Context) (Job, bool, error) {
	var j Job
	err := w.Pool.QueryRow(ctx, `
		UPDATE jobs SET status = 'running', lease_owner = $2,
			lease_expires_at = now() + make_interval(secs => $3),
			attempts = attempts + 1, updated_at = now()
		WHERE id = (
			SELECT id FROM jobs
			WHERE kind = $1 AND status = 'queued' AND run_at <= now()
			ORDER BY run_at, id LIMIT 1
			FOR UPDATE SKIP LOCKED)
		RETURNING id, kind, coalesce(dedup_key, ''), payload, attempts, max_attempts, last_error, run_at`,
		w.Kind, w.owner, w.LeaseTTL.Seconds(),
	).Scan(&j.ID, &j.Kind, &j.DedupKey, &j.Payload, &j.Attempts, &j.MaxAttempts, &j.LastError, &j.RunAt)
	if errors.Is(store.MapErr(err), store.ErrNotFound) {
		return Job{}, false, nil
	}
	if err != nil {
		return Job{}, false, err
	}
	return j, true, nil
}

// process runs the handler and records the outcome. It deliberately does not use
// the Run context: on shutdown, a job in progress finishes instead of being cut
// off half way.
func (w *Worker) process(job Job) {
	log := w.Log.With("kind", job.Kind, "job", job.ID, "attempt", job.Attempts)
	ctx, cancel := context.WithTimeout(context.Background(), w.handlerTimeout())
	err := w.safeHandle(ctx, job)
	cancel()

	db, done := context.WithTimeout(context.Background(), 5*time.Second)
	defer done()

	if err == nil {
		if !w.finish(db, job.ID, StatusSucceeded, "") {
			log.Warn("job finished after its lease was lost")
		}
		return
	}

	var perm *permanentError
	if errors.As(err, &perm) || job.Attempts >= job.MaxAttempts {
		if w.finish(db, job.ID, StatusFailed, err.Error()) && w.OnFailed != nil {
			job.LastError = err.Error()
			w.OnFailed(db, job, err)
		}
		log.Warn("job failed", "error", err)
		return
	}

	delay := w.Backoff.Delay(job.Attempts)
	var ra *retryAfterError
	if errors.As(err, &ra) {
		delay = ra.after
	}
	tag, uerr := w.Pool.Exec(db, `
		UPDATE jobs SET status = 'queued', run_at = now() + make_interval(secs => $3),
			last_error = $4, lease_owner = NULL, lease_expires_at = NULL, updated_at = now()
		WHERE id = $1 AND lease_owner = $2 AND status = 'running'`,
		job.ID, w.owner, delay.Seconds(), err.Error())
	if uerr != nil {
		log.Error("requeue job", "error", uerr)
	} else if tag.RowsAffected() == 0 {
		log.Warn("job lease was lost before it could be requeued")
	}
	log.Info("job will be retried", "error", err, "delay", delay)
}

// safeHandle turns a panic in the handler into an error, so one bad job cannot
// kill the worker goroutine.
func (w *Worker) safeHandle(ctx context.Context, job Job) (err error) {
	defer func() {
		if v := recover(); v != nil {
			err = fmt.Errorf("handler panicked: %v", v)
		}
	}()
	return w.Handler(ctx, job)
}

// finish moves a job this worker holds to a final status. It reports false if
// the lease was lost (the sweeper or another worker owns the job now).
func (w *Worker) finish(ctx context.Context, id int64, status, errMsg string) bool {
	tag, err := w.Pool.Exec(ctx, `
		UPDATE jobs SET status = $3, last_error = $4, finished_at = now(), updated_at = now(),
			lease_owner = NULL, lease_expires_at = NULL
		WHERE id = $1 AND lease_owner = $2 AND status = 'running'`, id, w.owner, status, errMsg)
	if err != nil {
		w.Log.Error("finish job", "job", id, "error", err)
		return false
	}
	return tag.RowsAffected() == 1
}

// Sweep requeues this kind's jobs whose lease expired, or fails them if that was
// their last attempt. Every process may run it; SKIP LOCKED keeps runs apart.
func (w *Worker) Sweep(ctx context.Context) {
	w.setDefaults()
	rows, err := w.Pool.Query(ctx, `
		WITH expired AS (
			SELECT id FROM jobs
			WHERE kind = $1 AND status = 'running' AND lease_expires_at < now()
			FOR UPDATE SKIP LOCKED)
		UPDATE jobs j SET
			status      = CASE WHEN j.attempts >= j.max_attempts THEN 'failed' ELSE 'queued' END,
			finished_at = CASE WHEN j.attempts >= j.max_attempts THEN now() END,
			run_at = now(), last_error = $2, lease_owner = NULL, lease_expires_at = NULL, updated_at = now()
		FROM expired WHERE j.id = expired.id
		RETURNING j.id, j.kind, coalesce(j.dedup_key, ''), j.payload, j.attempts, j.max_attempts, j.status`,
		w.Kind, ErrLeaseExpired.Error())
	if err != nil {
		if ctx.Err() == nil {
			w.Log.Error("sweep jobs", "kind", w.Kind, "error", err)
		}
		return
	}
	var failed []Job
	requeued := 0
	for rows.Next() {
		var j Job
		var status string
		if err := rows.Scan(&j.ID, &j.Kind, &j.DedupKey, &j.Payload, &j.Attempts, &j.MaxAttempts, &status); err != nil {
			w.Log.Error("sweep jobs: scan", "error", err)
			continue
		}
		j.LastError = ErrLeaseExpired.Error()
		if status == StatusFailed {
			failed = append(failed, j)
		} else {
			requeued++
		}
	}
	rows.Close()

	if requeued > 0 {
		w.Log.Warn("requeued jobs whose worker stopped", "kind", w.Kind, "count", requeued)
		events.Ring(ctx, w.Pool, Topic(w.Kind))
	}
	for _, j := range failed {
		if w.OnFailed != nil {
			w.OnFailed(ctx, j, ErrLeaseExpired)
		}
	}
}

package queue_test

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"os"
	"strconv"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"campaign-composer/internal/backoff"
	"campaign-composer/internal/events"
	"campaign-composer/internal/queue"
	"campaign-composer/internal/testdb"
)

func TestMain(m *testing.M) { os.Exit(testdb.Main(m)) }

var quiet = slog.New(slog.NewTextHandler(io.Discard, nil))

// fast keeps retries quick in tests.
var fast = backoff.Policy{Base: 5 * time.Millisecond, Max: 20 * time.Millisecond}

func startWorker(t *testing.T, w *queue.Worker) {
	t.Helper()
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { w.Run(ctx); close(done) }()
	t.Cleanup(func() { cancel(); <-done })
}

func waitFor(t *testing.T, what string, cond func() bool) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for !cond() {
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for %s", what)
		}
		time.Sleep(10 * time.Millisecond)
	}
}

type jobRow struct {
	Status    string
	Attempts  int
	LastError string
}

func row(t *testing.T, pool *pgxpool.Pool, id int64) jobRow {
	t.Helper()
	var r jobRow
	if err := pool.QueryRow(context.Background(),
		`SELECT status, attempts, last_error FROM jobs WHERE id = $1`, id).Scan(&r.Status, &r.Attempts, &r.LastError); err != nil {
		t.Fatal(err)
	}
	return r
}

func countStatus(t *testing.T, pool *pgxpool.Pool, kind, status string) int {
	t.Helper()
	var n int
	pool.QueryRow(context.Background(), `SELECT count(*) FROM jobs WHERE kind = $1 AND status = $2`, kind, status).Scan(&n)
	return n
}

func TestEnqueueDedup(t *testing.T) {
	pool := testdb.New(t)
	ctx := context.Background()

	id1, created1, err := queue.Enqueue(ctx, pool, "send", map[string]int{"n": 1}, queue.EnqueueOptions{DedupKey: "delivery:42"})
	if err != nil || !created1 {
		t.Fatalf("first enqueue: id=%d created=%v err=%v", id1, created1, err)
	}
	_, created2, err := queue.Enqueue(ctx, pool, "send", map[string]int{"n": 2}, queue.EnqueueOptions{DedupKey: "delivery:42"})
	if err != nil || created2 {
		t.Fatalf("second enqueue: created=%v err=%v; want a silent no-op", created2, err)
	}
	// Jobs without a key are never deduplicated.
	for range 2 {
		if _, created, err := queue.Enqueue(ctx, pool, "send", nil, queue.EnqueueOptions{}); err != nil || !created {
			t.Fatalf("keyless enqueue: created=%v err=%v", created, err)
		}
	}
	if n := countStatus(t, pool, "send", queue.StatusQueued); n != 3 {
		t.Fatalf("queued jobs = %d, want 3", n)
	}
}

func TestEachJobRunsExactlyOnceAcrossWorkers(t *testing.T) {
	pool := testdb.New(t)
	ctx := context.Background()
	const jobs = 200

	var mu sync.Mutex
	seen := map[string]int{}
	handler := func(ctx context.Context, j queue.Job) error {
		mu.Lock()
		seen[string(j.Payload)]++
		mu.Unlock()
		return nil
	}
	// Two independent workers (as if two processes), eight goroutines each.
	for range 2 {
		startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "send", Handler: handler,
			Concurrency: 8, PollEvery: 10 * time.Millisecond})
	}
	for i := range jobs {
		if _, _, err := queue.Enqueue(ctx, pool, "send", strconv.Itoa(i), queue.EnqueueOptions{}); err != nil {
			t.Fatal(err)
		}
	}
	waitFor(t, "all jobs to succeed", func() bool { return countStatus(t, pool, "send", queue.StatusSucceeded) == jobs })

	mu.Lock()
	defer mu.Unlock()
	if len(seen) != jobs {
		t.Fatalf("handled %d distinct jobs, want %d", len(seen), jobs)
	}
	for k, n := range seen {
		if n != 1 {
			t.Fatalf("job %s ran %d times", k, n)
		}
	}
}

func TestRetriesThenSucceeds(t *testing.T) {
	pool := testdb.New(t)
	var calls atomic.Int32
	startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "flaky", Backoff: fast, PollEvery: 5 * time.Millisecond,
		Handler: func(ctx context.Context, j queue.Job) error {
			if calls.Add(1) < 3 {
				return errors.New("provider returned 503")
			}
			return nil
		}})
	id, _, _ := queue.Enqueue(context.Background(), pool, "flaky", nil, queue.EnqueueOptions{})

	waitFor(t, "success", func() bool { return row(t, pool, id).Status == queue.StatusSucceeded })
	if r := row(t, pool, id); r.Attempts != 3 || r.LastError != "" {
		t.Fatalf("row = %+v, want 3 attempts and the error cleared", r)
	}
}

func TestRetryAfterIsRespected(t *testing.T) {
	pool := testdb.New(t)
	ctx := context.Background()
	var calls atomic.Int32
	startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "limited", Backoff: fast, PollEvery: 5 * time.Millisecond,
		Handler: func(ctx context.Context, j queue.Job) error {
			calls.Add(1)
			return queue.RetryAfter(errors.New("429 too many requests"), 3*time.Second)
		}})
	id, _, _ := queue.Enqueue(ctx, pool, "limited", nil, queue.EnqueueOptions{})

	waitFor(t, "first attempt", func() bool { return calls.Load() == 1 && row(t, pool, id).Status == queue.StatusQueued })
	var wait float64
	pool.QueryRow(ctx, `SELECT extract(epoch FROM run_at - now()) FROM jobs WHERE id = $1`, id).Scan(&wait)
	if wait < 2 || wait > 3.1 {
		t.Fatalf("next attempt in %.2fs, want about 3s (Retry-After), not the %s backoff", wait, fast.Max)
	}
	time.Sleep(200 * time.Millisecond)
	if n := calls.Load(); n != 1 {
		t.Fatalf("handler called %d times before Retry-After passed", n)
	}
}

func TestPermanentErrorAndExhaustedAttemptsFail(t *testing.T) {
	pool := testdb.New(t)
	ctx := context.Background()

	var mu sync.Mutex
	failed := map[int64]string{}
	startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "bad", Backoff: fast, PollEvery: 5 * time.Millisecond,
		Handler: func(ctx context.Context, j queue.Job) error {
			if string(j.Payload) == `"invalid"` {
				return queue.Permanent(errors.New("400 invalid phone number"))
			}
			return errors.New("503 unavailable")
		},
		OnFailed: func(ctx context.Context, j queue.Job, err error) {
			mu.Lock()
			defer mu.Unlock()
			if _, dup := failed[j.ID]; dup {
				t.Errorf("OnFailed called twice for job %d", j.ID)
			}
			failed[j.ID] = err.Error()
		}})

	permID, _, _ := queue.Enqueue(ctx, pool, "bad", "invalid", queue.EnqueueOptions{})
	retryID, _, _ := queue.Enqueue(ctx, pool, "bad", "down", queue.EnqueueOptions{MaxAttempts: 3})

	waitFor(t, "both to fail", func() bool {
		mu.Lock()
		defer mu.Unlock()
		return len(failed) == 2
	})
	if r := row(t, pool, permID); r.Status != queue.StatusFailed || r.Attempts != 1 {
		t.Errorf("permanent: %+v, want failed after 1 attempt", r)
	}
	if r := row(t, pool, retryID); r.Status != queue.StatusFailed || r.Attempts != 3 || r.LastError != "503 unavailable" {
		t.Errorf("exhausted: %+v, want failed after 3 attempts", r)
	}
}

func TestPanicIsRetriedNotFatal(t *testing.T) {
	pool := testdb.New(t)
	var calls atomic.Int32
	startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "panicky", Backoff: fast, PollEvery: 5 * time.Millisecond,
		Handler: func(ctx context.Context, j queue.Job) error {
			if calls.Add(1) == 1 {
				panic("boom")
			}
			return nil
		}})
	id, _, _ := queue.Enqueue(context.Background(), pool, "panicky", nil, queue.EnqueueOptions{})
	waitFor(t, "success after a panic", func() bool { return row(t, pool, id).Status == queue.StatusSucceeded })
}

func TestSweepRequeuesExpiredLeases(t *testing.T) {
	pool := testdb.New(t)
	ctx := context.Background()

	// Simulate two jobs whose worker died mid-way: one with attempts left, one on its last.
	var alive, last int64
	pool.QueryRow(ctx, `INSERT INTO jobs (kind, status, attempts, max_attempts, lease_owner, lease_expires_at)
		VALUES ('crash', 'running', 1, 5, 'dead-worker', now() - interval '1 second') RETURNING id`).Scan(&alive)
	pool.QueryRow(ctx, `INSERT INTO jobs (kind, status, attempts, max_attempts, lease_owner, lease_expires_at)
		VALUES ('crash', 'running', 5, 5, 'dead-worker', now() - interval '1 second') RETURNING id`).Scan(&last)
	// A live lease must not be touched.
	var live int64
	pool.QueryRow(ctx, `INSERT INTO jobs (kind, status, attempts, lease_owner, lease_expires_at)
		VALUES ('crash', 'running', 1, 'busy-worker', now() + interval '1 minute') RETURNING id`).Scan(&live)

	var failed []int64
	w := &queue.Worker{Pool: pool, Log: quiet, Kind: "crash",
		OnFailed: func(ctx context.Context, j queue.Job, err error) {
			if !errors.Is(err, queue.ErrLeaseExpired) {
				t.Errorf("OnFailed err = %v", err)
			}
			failed = append(failed, j.ID)
		}}
	w.Sweep(ctx)

	if r := row(t, pool, alive); r.Status != queue.StatusQueued {
		t.Errorf("job with attempts left: %+v, want queued", r)
	}
	if r := row(t, pool, last); r.Status != queue.StatusFailed {
		t.Errorf("job on its last attempt: %+v, want failed", r)
	}
	if r := row(t, pool, live); r.Status != queue.StatusRunning {
		t.Errorf("live lease: %+v, want untouched", r)
	}
	if len(failed) != 1 || failed[0] != last {
		t.Errorf("OnFailed for %v, want [%d]", failed, last)
	}
}

func TestDoorbellWakesIdleWorkers(t *testing.T) {
	pool := testdb.New(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	hub := events.NewHub(pool, quiet)
	go hub.Run(ctx)
	<-hub.Ready()

	var done atomic.Bool
	startWorker(t, &queue.Worker{Pool: pool, Hub: hub, Log: quiet, Kind: "wake",
		PollEvery: time.Minute, // polling alone would take a minute
		Handler: func(ctx context.Context, j queue.Job) error { done.Store(true); return nil }})
	time.Sleep(100 * time.Millisecond) // let the workers go idle

	start := time.Now()
	queue.Enqueue(ctx, pool, "wake", nil, queue.EnqueueOptions{})
	waitFor(t, "the doorbell to wake a worker", done.Load)
	if d := time.Since(start); d > 2*time.Second {
		t.Fatalf("took %s; the doorbell did not wake the worker", d)
	}
}

func TestScheduledJobWaitsForRunAt(t *testing.T) {
	pool := testdb.New(t)
	var ran atomic.Bool
	startWorker(t, &queue.Worker{Pool: pool, Log: quiet, Kind: "later", PollEvery: 10 * time.Millisecond,
		Handler: func(ctx context.Context, j queue.Job) error { ran.Store(true); return nil }})
	queue.Enqueue(context.Background(), pool, "later", nil, queue.EnqueueOptions{RunAt: time.Now().Add(time.Hour)})
	time.Sleep(200 * time.Millisecond)
	if ran.Load() {
		t.Fatal("a job scheduled an hour ahead ran now")
	}
}

package api

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"time"

	"campaign-composer/internal/events"
)

// keepAliveEvery also bounds how late a missed doorbell can delay an event.
var keepAliveEvery = 15 * time.Second

// streamTopic streams a topic's events with server-sent events. Ported from the
// agents-platform run stream.
//
// It first replays stored events after Last-Event-ID (sent by the browser when
// it reconnects) or ?after=, then waits for new ones. Stored and live events come
// from the same query, so nothing falls in between. Streamed text arrives as
// "delta" events, which are not stored. When finished reports true after a
// read, the stream sends "end" so the browser does not reconnect.
func (s *Server) streamTopic(w http.ResponseWriter, r *http.Request, topic string,
	finished func(ctx context.Context) (bool, error)) {
	ctx := r.Context()
	after, _ := strconv.ParseInt(r.Header.Get("Last-Event-ID"), 10, 64)
	if v := r.URL.Query().Get("after"); v != "" {
		after, _ = strconv.ParseInt(v, 10, 64)
	}

	// Subscribe before the first query, so an event stored in between still
	// rings the bell.
	sub := s.hub.Subscribe(topic)
	defer s.hub.Unsubscribe(sub)

	rc := http.NewResponseController(w)
	h := w.Header()
	h.Set("Content-Type", "text/event-stream")
	h.Set("Cache-Control", "no-cache")
	h.Set("X-Accel-Buffering", "no") // tell proxies not to buffer
	w.WriteHeader(http.StatusOK)
	io.WriteString(w, "retry: 2000\n\n")
	rc.Flush()

	keepAlive := time.NewTicker(keepAliveEvery)
	defer keepAlive.Stop()
	for {
		evs, err := events.Since(ctx, s.pool, topic, after)
		if err != nil {
			return
		}
		for _, ev := range evs {
			data, _ := json.Marshal(ev)
			fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", ev.Seq, ev.Type, data)
			after = ev.Seq
		}
		rc.Flush()
		if finished != nil {
			if done, err := finished(ctx); err != nil || done {
				io.WriteString(w, "event: end\ndata: {}\n\n")
				rc.Flush()
				return
			}
		}

	wait:
		for {
			select {
			case <-ctx.Done():
				return
			case <-s.closing:
				return
			case <-keepAlive.C:
				io.WriteString(w, ": keep-alive\n\n")
				rc.Flush()
				break wait // also re-reads, in case a doorbell was missed
			case sig := <-sub.C:
				if sig.Delta == "" {
					break wait
				}
				data, _ := json.Marshal(map[string]string{"text": sig.Delta})
				fmt.Fprintf(w, "event: delta\ndata: %s\n\n", data)
				rc.Flush()
			}
		}
	}
}

package api

import (
	"bufio"
	"context"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"campaign-composer/internal/events"
	"campaign-composer/internal/testdb"
)

func TestMain(m *testing.M) { os.Exit(testdb.Main(m)) }

var quiet = slog.New(slog.NewTextHandler(io.Discard, nil))

func newTestServer(t *testing.T) (*Server, *httptest.Server) {
	t.Helper()
	pool := testdb.New(t)
	ctx, cancel := context.WithCancel(context.Background())
	hub := events.NewHub(pool, quiet)
	go hub.Run(ctx)
	<-hub.Ready()
	s := New(pool, quiet, Options{Hub: hub})
	ts := httptest.NewServer(s.Handler())
	t.Cleanup(func() { s.CloseStreams(); ts.Close(); cancel() })
	return s, ts
}

func TestHealthAndReady(t *testing.T) {
	_, ts := newTestServer(t)
	for path, want := range map[string]string{"/healthz": `"ok"`, "/readyz": `"ready"`} {
		resp, err := http.Get(ts.URL + path)
		if err != nil {
			t.Fatal(err)
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != 200 || !strings.Contains(string(body), want) {
			t.Errorf("%s: %d %s", path, resp.StatusCode, body)
		}
	}
	resp, _ := http.Get(ts.URL + "/api/nope")
	if resp.StatusCode != 404 || resp.Header.Get("Content-Type") != "application/json" {
		t.Errorf("unknown api path: %d %s", resp.StatusCode, resp.Header.Get("Content-Type"))
	}
	resp.Body.Close()
}

func TestDecodeJSONIsStrict(t *testing.T) {
	type req struct {
		Brief string `json:"brief"`
	}
	for body, wantOK := range map[string]bool{
		`{"brief": "hi"}`:                 true,
		`{"brief": "hi", "extra": 1}`:     false, // unknown field
		`{"brief": "hi"} {"brief": "x"}`: false, // trailing data
		`not json`:                        false,
	} {
		rec := httptest.NewRecorder()
		r := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(body))
		var v req
		if ok := decodeJSON(rec, r, &v); ok != wantOK {
			t.Errorf("%q: ok=%v, want %v (%s)", body, ok, wantOK, rec.Body.String())
		}
	}
}

func TestRecoverPanics(t *testing.T) {
	s := New(nil, quiet, Options{})
	h := s.recoverPanics(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { panic("boom") }))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
	if rec.Code != 500 || strings.Contains(rec.Body.String(), "boom") {
		t.Fatalf("got %d %q; want a 500 that hides the panic", rec.Code, rec.Body.String())
	}
}

// sseReader reads "event: X" names (and delta text) from a stream.
func readEvents(t *testing.T, body io.Reader, n int) []string {
	t.Helper()
	sc := bufio.NewScanner(body)
	var got []string
	for len(got) < n && sc.Scan() {
		line := sc.Text()
		if name, ok := strings.CutPrefix(line, "event: "); ok {
			got = append(got, name)
		}
		if data, ok := strings.CutPrefix(line, "data: "); ok && len(got) > 0 && got[len(got)-1] == "delta" {
			got[len(got)-1] = "delta:" + data
		}
	}
	return got
}

func TestStreamReplaysThenFollowsLive(t *testing.T) {
	s, ts := newTestServer(t)
	ctx := context.Background()
	const topic = "campaign:1"
	var finished atomic.Bool

	mux := http.NewServeMux()
	mux.HandleFunc("GET /stream", func(w http.ResponseWriter, r *http.Request) {
		s.streamTopic(w, r, topic, func(context.Context) (bool, error) { return finished.Load(), nil })
	})
	streamSrv := httptest.NewServer(mux)
	defer streamSrv.Close()
	_ = ts

	events.Add(ctx, s.pool, topic, "created", nil)
	events.Add(ctx, s.pool, topic, "audience_ready", nil)

	// Reconnect after event 1: only event 2 is replayed.
	req, _ := http.NewRequest(http.MethodGet, streamSrv.URL+"/stream", nil)
	req.Header.Set("Last-Event-ID", "1")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if ct := resp.Header.Get("Content-Type"); ct != "text/event-stream" {
		t.Fatalf("content type %q", ct)
	}

	go func() {
		time.Sleep(200 * time.Millisecond)
		events.Delta(ctx, s.pool, topic, "Merhaba")
		time.Sleep(100 * time.Millisecond)
		finished.Store(true)
		events.Add(ctx, s.pool, topic, "content_ready", nil)
	}()

	got := readEvents(t, resp.Body, 4)
	want := []string{"audience_ready", `delta:{"text":"Merhaba"}`, "content_ready", "end"}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("events = %v, want %v", got, want)
	}
}

// Command server runs the Campaign Composer API, the event hub and (later) the
// delivery workers in one process.
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"campaign-composer/internal/api"
	"campaign-composer/internal/config"
	"campaign-composer/internal/events"
	"campaign-composer/internal/store"
)

func main() {
	if err := run(); err != nil {
		slog.Error("server stopped", "error", err)
		os.Exit(1)
	}
}

func run() error {
	cfg, err := config.Load(".env")
	if err != nil {
		return err
	}
	log := newLogger(cfg.LogJSON)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	pool, closeDB, err := store.Open(ctx, cfg.DatabaseURL, cfg.DataDir, log)
	if err != nil {
		return err
	}
	defer closeDB()
	if err := store.Migrate(ctx, pool); err != nil {
		return err
	}

	// Background work stops when bgCtx is cancelled, after HTTP has shut down.
	bgCtx, stopBg := context.WithCancel(context.Background())
	defer stopBg()
	hub := events.NewHub(pool, log)
	go hub.Run(bgCtx)

	apiSrv := api.New(pool, log, api.Options{Hub: hub})
	srv := &http.Server{
		Addr:              ":" + cfg.Port,
		Handler:           apiSrv.Handler(),
		ReadHeaderTimeout: 10 * time.Second,
	}
	errc := make(chan error, 1)
	go func() {
		log.Info("listening", "port", cfg.Port, "llm", llmMode(cfg))
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errc <- err
		}
	}()

	select {
	case <-ctx.Done():
	case err := <-errc:
		return err
	}
	log.Info("shutting down")
	apiSrv.CloseStreams()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Error("http shutdown", "error", err)
	}
	stopBg()
	return nil
}

func llmMode(cfg config.Config) string {
	if cfg.AnthropicAPIKey == "" {
		return "mock"
	}
	return "claude:" + cfg.AnthropicModel
}

func newLogger(json bool) *slog.Logger {
	if json {
		return slog.New(slog.NewJSONHandler(os.Stdout, nil))
	}
	return slog.New(slog.NewTextHandler(os.Stdout, nil))
}

