// Package llm is the provider-neutral model interface, ported from agents-platform
// and narrowed to what this app needs: one system prompt, a short conversation,
// a JSON schema the answer must follow, and streamed text.
package llm

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"
)

type Role string

const (
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
)

type Message struct {
	Role Role   `json:"role"`
	Text string `json:"text"`
}

type Request struct {
	// Task names the job ("audience", "content"). Logs and metrics use it, and
	// the keyword mock uses it to know what to answer.
	Task     string
	System   string
	Messages []Message
	// Schema, if set, is the JSON schema the answer must follow (structured outputs).
	Schema    map[string]any
	MaxTokens int
}

type Usage struct {
	InputTokens  int `json:"input_tokens"`
	OutputTokens int `json:"output_tokens"`
}

type Response struct {
	Text       string
	Model      string
	StopReason string
	Usage      Usage
}

// Provider is one model API. onText receives text as it streams and may be nil.
type Provider interface {
	Name() string
	Generate(ctx context.Context, req Request, onText func(string)) (Response, error)
}

// StatusError is an HTTP error from a provider, returned before any output was
// streamed, so the call can safely be retried.
type StatusError struct {
	Provider   string
	StatusCode int
	Message    string
	// RetryAfter is how long the provider asked us to wait, if it said.
	RetryAfter time.Duration
}

func (e *StatusError) Error() string {
	return fmt.Sprintf("%s returned HTTP %d: %s", e.Provider, e.StatusCode, e.Message)
}

// Temporary reports whether retrying may succeed: rate limits and overload.
func (e *StatusError) Temporary() bool {
	switch e.StatusCode {
	case 408, 429, 500, 502, 503, 504, 529:
		return true
	}
	return false
}

// ErrRefused means the model declined the request (stop reason "refusal").
var ErrRefused = errors.New("the model declined this request")

// ErrTruncated means the answer hit the token limit, so structured output is
// incomplete.
var ErrTruncated = errors.New("the model's answer was cut off at the token limit")

// cleanMessage shortens a provider error message and removes the key, in case a
// provider ever echoes it.
func cleanMessage(msg, apiKey string) string {
	msg = strings.TrimSpace(msg)
	if apiKey != "" {
		msg = strings.ReplaceAll(msg, apiKey, "***")
	}
	if len(msg) > 500 {
		msg = msg[:500] + "…"
	}
	return msg
}

// parseRetryAfter reads a Retry-After header: seconds or an HTTP date.
func parseRetryAfter(v string) time.Duration {
	v = strings.TrimSpace(v)
	if v == "" {
		return 0
	}
	if d, err := time.ParseDuration(v + "s"); err == nil && d >= 0 {
		return d
	}
	if t, err := time.Parse(time.RFC1123, v); err == nil {
		return max(time.Until(t), 0)
	}
	return 0
}

package llm

import (
	"context"
	"errors"
	"fmt"
	"time"

	"campaign-composer/internal/backoff"
)

type RetryPolicy struct {
	// MaxAttempts counts the first call too.
	MaxAttempts int
	Backoff     backoff.Policy
	// MaxWait caps a single wait. If the provider asks for longer, the call
	// fails at once with a clear error instead of keeping the marketer waiting.
	MaxWait time.Duration
}

var DefaultRetry = RetryPolicy{
	MaxAttempts: 3,
	Backoff:     backoff.Policy{Base: time.Second, Max: 8 * time.Second},
	MaxWait:     20 * time.Second,
}

// GenerateWithRetry calls the provider and retries rate limits and temporary
// server errors, waiting as long as the provider asks (Retry-After) or backing
// off with jitter. Errors after output started streaming are not StatusErrors,
// so a half-streamed answer is never repeated.
func GenerateWithRetry(ctx context.Context, p Provider, req Request, onText func(string), pol RetryPolicy) (Response, error) {
	for attempt := 1; ; attempt++ {
		resp, err := p.Generate(ctx, req, onText)
		var se *StatusError
		if err == nil || !errors.As(err, &se) || !se.Temporary() {
			return resp, err
		}
		if attempt >= pol.MaxAttempts {
			return resp, fmt.Errorf("gave up after %d attempts: %w", attempt, err)
		}
		wait := se.RetryAfter
		if wait == 0 {
			wait = pol.Backoff.Delay(attempt)
		}
		if wait > pol.MaxWait {
			return resp, fmt.Errorf("%w (the provider asked to wait %s, longer than the %s limit)",
				err, wait.Round(time.Second), pol.MaxWait)
		}
		t := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			t.Stop()
			return Response{}, context.Cause(ctx)
		case <-t.C:
		}
	}
}

// Package llmtest provides a scripted model provider for tests. Ported from
// agents-platform.
package llmtest

import (
	"context"
	"errors"
	"sync"

	"campaign-composer/internal/llm"
)

// Step produces one model response.
type Step func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error)

// Fake returns its steps in order, one per Generate call, and records what it
// was asked.
type Fake struct {
	mu       sync.Mutex
	steps    []Step
	requests []llm.Request
}

func New(steps ...Step) *Fake { return &Fake{steps: steps} }

func (f *Fake) Name() string { return "fake" }

// Script replaces the remaining steps.
func (f *Fake) Script(steps ...Step) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.steps = steps
}

func (f *Fake) Generate(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
	f.mu.Lock()
	f.requests = append(f.requests, req)
	if len(f.steps) == 0 {
		f.mu.Unlock()
		return llm.Response{}, errors.New("fake provider: no scripted response left")
	}
	step := f.steps[0]
	f.steps = f.steps[1:]
	f.mu.Unlock()
	return step(ctx, req, onText)
}

// Requests returns copies of the requests received so far.
func (f *Fake) Requests() []llm.Request {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]llm.Request(nil), f.requests...)
}

var usage = llm.Usage{InputTokens: 100, OutputTokens: 20}

// Text answers with text, streamed in two pieces.
func Text(s string) Step {
	return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
		if onText != nil && len(s) > 1 {
			onText(s[:len(s)/2])
			onText(s[len(s)/2:])
		}
		return llm.Response{Text: s, Model: "fake", StopReason: "end_turn", Usage: usage}, nil
	}
}

// Fail returns err.
func Fail(err error) Step {
	return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
		return llm.Response{}, err
	}
}

// Wait blocks until release is closed or the call is cancelled, then runs next.
func Wait(release <-chan struct{}, next Step) Step {
	return func(ctx context.Context, req llm.Request, onText func(string)) (llm.Response, error) {
		select {
		case <-release:
			return next(ctx, req, onText)
		case <-ctx.Done():
			return llm.Response{}, context.Cause(ctx)
		}
	}
}

package llm_test

import (
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	"campaign-composer/internal/backoff"
	"campaign-composer/internal/llm"
	"campaign-composer/internal/llm/llmtest"
)

var fastRetry = llm.RetryPolicy{MaxAttempts: 3, Backoff: backoff.Policy{Base: time.Millisecond, Max: 5 * time.Millisecond}, MaxWait: time.Second}

func TestRetryOnRateLimitThenSucceed(t *testing.T) {
	fake := llmtest.New(
		llmtest.Fail(&llm.StatusError{Provider: "p", StatusCode: 429, RetryAfter: 10 * time.Millisecond}),
		llmtest.Fail(&llm.StatusError{Provider: "p", StatusCode: 529}),
		llmtest.Text(`{"ok":true}`),
	)
	resp, err := llm.GenerateWithRetry(context.Background(), fake, llm.Request{}, nil, fastRetry)
	if err != nil || resp.Text != `{"ok":true}` || len(fake.Requests()) != 3 {
		t.Fatalf("resp=%+v err=%v calls=%d", resp, err, len(fake.Requests()))
	}
}

func TestNoRetryOnPermanentErrors(t *testing.T) {
	for _, err := range []error{
		&llm.StatusError{Provider: "p", StatusCode: 400, Message: "bad request"},
		&llm.StatusError{Provider: "p", StatusCode: 401},
		llm.ErrRefused,
		errors.New("stream broke after output started"),
	} {
		fake := llmtest.New(llmtest.Fail(err), llmtest.Text("never"))
		if _, got := llm.GenerateWithRetry(context.Background(), fake, llm.Request{}, nil, fastRetry); !errors.Is(got, err) {
			t.Errorf("err = %v, want %v unchanged", got, err)
		}
		if n := len(fake.Requests()); n != 1 {
			t.Errorf("%v: called %d times, want 1", err, n)
		}
	}
}

func TestGiveUpAfterMaxAttempts(t *testing.T) {
	busy := &llm.StatusError{Provider: "p", StatusCode: 503}
	fake := llmtest.New(llmtest.Fail(busy), llmtest.Fail(busy), llmtest.Fail(busy), llmtest.Text("late"))
	_, err := llm.GenerateWithRetry(context.Background(), fake, llm.Request{}, nil, fastRetry)
	if !errors.Is(err, busy) || !strings.Contains(err.Error(), "gave up after 3 attempts") {
		t.Fatalf("err = %v", err)
	}
}

func TestRetryAfterLongerThanLimitFailsFast(t *testing.T) {
	fake := llmtest.New(llmtest.Fail(&llm.StatusError{Provider: "p", StatusCode: 429, RetryAfter: time.Hour}))
	start := time.Now()
	_, err := llm.GenerateWithRetry(context.Background(), fake, llm.Request{}, nil, fastRetry)
	if err == nil || !strings.Contains(err.Error(), "longer than") || time.Since(start) > time.Second {
		t.Fatalf("err = %v after %s", err, time.Since(start))
	}
}

package llm

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"github.com/anthropics/anthropic-sdk-go/v2"
	"github.com/anthropics/anthropic-sdk-go/v2/option"
)

// Anthropic calls Claude through the official SDK. Every call streams, so long
// answers never hit HTTP timeouts and the UI can show text as it arrives.
type Anthropic struct {
	client anthropic.Client
	model  string
	effort anthropic.BetaOutputConfigEffort
	apiKey string // only to scrub it from error messages
}

type AnthropicOptions struct {
	APIKey string
	Model  string
	// Effort is "low", "medium" or "high". The tasks here are short and
	// structured, so low keeps them fast and cheap.
	Effort string
	// BaseURL and HTTPClient let tests point the SDK at a local server.
	BaseURL    string
	HTTPClient *http.Client
}

func NewAnthropic(o AnthropicOptions) *Anthropic {
	opts := []option.RequestOption{
		option.WithAPIKey(o.APIKey),
		// GenerateWithRetry is the one retry policy, so it can honor Retry-After
		// and never repeat a half-streamed answer.
		option.WithMaxRetries(0),
	}
	if o.BaseURL != "" {
		opts = append(opts, option.WithBaseURL(o.BaseURL))
	}
	if o.HTTPClient != nil {
		opts = append(opts, option.WithHTTPClient(o.HTTPClient))
	}
	if o.Effort == "" {
		o.Effort = "low"
	}
	return &Anthropic{
		client: anthropic.NewClient(opts...),
		model:  o.Model,
		effort: anthropic.BetaOutputConfigEffort(o.Effort),
		apiKey: o.APIKey,
	}
}

func (a *Anthropic) Name() string { return "claude:" + a.model }

// fallbackModels support the server-side refusal fallback: a request the model
// declines is answered by a fallback model in the same call. Haiku does not.
var fallbackModels = map[string]bool{
	"claude-opus-5-5": true, "claude-opus-5": true, "claude-sonnet-5-5": true,
	"claude-fable-5-2": true, "claude-fable-5-1": true,
}

const defaultMaxTokens = 8000

func (a *Anthropic) Generate(ctx context.Context, req Request, onText func(string)) (Response, error) {
	maxTokens := req.MaxTokens
	if maxTokens <= 0 {
		maxTokens = defaultMaxTokens
	}
	params := anthropic.BetaMessageNewParams{
		Model:        a.model,
		MaxTokens:    int64(maxTokens),
		Messages:     toParams(req.Messages),
		OutputConfig: anthropic.BetaOutputConfigParam{Effort: a.effort},
	}
	if req.System != "" {
		params.System = []anthropic.BetaTextBlockParam{{Text: req.System}}
	}
	if req.Schema != nil {
		params.OutputConfig.Format = anthropic.BetaJSONOutputFormatParam{Schema: req.Schema}
	}
	if fallbackModels[a.model] {
		params.Fallbacks = anthropic.BetaFallbacksParamOfDefault()
		params.Betas = append(params.Betas, anthropic.AnthropicBetaServerSideFallback2026_07_01)
	}

	stream := a.client.Beta.Messages.NewStreaming(ctx, params)
	defer stream.Close()

	var msg anthropic.BetaMessage
	streamed := false
	for stream.Next() {
		ev := stream.Current()
		if err := msg.Accumulate(ev); err != nil {
			return Response{}, fmt.Errorf("claude stream: %w", err)
		}
		if d, ok := ev.AsAny().(anthropic.BetaRawContentBlockDeltaEvent); ok {
			if td, ok := d.Delta.AsAny().(anthropic.BetaTextDelta); ok && td.Text != "" {
				streamed = true
				if onText != nil {
					onText(td.Text)
				}
			}
		}
	}
	if err := stream.Err(); err != nil {
		return Response{}, a.mapErr(ctx, err, streamed)
	}

	var text strings.Builder
	for _, block := range msg.Content {
		if tb, ok := block.AsAny().(anthropic.BetaTextBlock); ok {
			text.WriteString(tb.Text)
		}
	}
	resp := Response{
		Text:       text.String(),
		Model:      string(msg.Model),
		StopReason: string(msg.StopReason),
		Usage:      Usage{InputTokens: int(msg.Usage.InputTokens), OutputTokens: int(msg.Usage.OutputTokens)},
	}
	switch resp.StopReason {
	case "refusal":
		return resp, ErrRefused
	case "max_tokens":
		return resp, ErrTruncated
	}
	return resp, nil
}

// mapErr turns SDK errors into StatusErrors (retryable when temporary) as long
// as no text has streamed yet. After that, a retry would repeat output, so the
// error is returned as it is.
func (a *Anthropic) mapErr(ctx context.Context, err error, streamed bool) error {
	if cause := context.Cause(ctx); cause != nil {
		return cause
	}
	if streamed {
		return fmt.Errorf("claude stream broke after output started: %s", cleanMessage(err.Error(), a.apiKey))
	}
	var apiErr *anthropic.Error
	if errors.As(err, &apiErr) {
		se := &StatusError{Provider: "claude", StatusCode: apiErr.StatusCode, Message: cleanMessage(apiErr.Error(), a.apiKey)}
		if apiErr.Response != nil {
			se.RetryAfter = parseRetryAfter(apiErr.Response.Header.Get("Retry-After"))
		}
		return se
	}
	// A connection error or an error event (e.g. overloaded) before any
	// output: nothing was shown yet, so it is safe to try again.
	return &StatusError{Provider: "claude", StatusCode: http.StatusServiceUnavailable, Message: cleanMessage(err.Error(), a.apiKey)}
}

func toParams(msgs []Message) []anthropic.BetaMessageParam {
	out := make([]anthropic.BetaMessageParam, 0, len(msgs))
	for _, m := range msgs {
		block := anthropic.NewBetaTextBlock(m.Text)
		if m.Role == RoleAssistant {
			out = append(out, anthropic.BetaMessageParam{
				Role:    anthropic.BetaMessageParamRoleAssistant,
				Content: []anthropic.BetaContentBlockParamUnion{block},
			})
			continue
		}
		out = append(out, anthropic.NewBetaUserMessage(block))
	}
	return out
}

