// Package webhook signs and verifies delivery-receipt webhooks with HMAC-SHA256.
//
// The signature covers the timestamp and the raw body ("<unix seconds>.<body>"),
// so a body cannot be replayed with a fresh timestamp, and old requests are
// refused after a tolerance window.
package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
	"time"
)

const (
	SignatureHeader = "X-Signature"
	TimestampHeader = "X-Timestamp"
	// Tolerance is how old (or how far in the future) a timestamp may be.
	Tolerance = 5 * time.Minute
)

var (
	ErrMissing   = errors.New("missing signature or timestamp")
	ErrBadFormat = errors.New("malformed signature or timestamp")
	ErrStale     = errors.New("timestamp outside the accepted window")
	ErrMismatch  = errors.New("signature does not match")
)

// Sign returns the header value for body sent at ts.
func Sign(secret string, ts time.Time, body []byte) string {
	return "sha256=" + hex.EncodeToString(mac(secret, ts.Unix(), body))
}

// Verify checks a request's signature and timestamp headers against its body.
func Verify(secret, signature, timestamp string, body []byte, now time.Time) error {
	if signature == "" || timestamp == "" {
		return ErrMissing
	}
	unix, err := strconv.ParseInt(timestamp, 10, 64)
	if err != nil {
		return ErrBadFormat
	}
	got, err := hex.DecodeString(strings.TrimPrefix(signature, "sha256="))
	if err != nil || !strings.HasPrefix(signature, "sha256=") {
		return ErrBadFormat
	}
	if d := now.Sub(time.Unix(unix, 0)); d > Tolerance || d < -Tolerance {
		return ErrStale
	}
	if !hmac.Equal(got, mac(secret, unix, body)) { // constant time
		return ErrMismatch
	}
	return nil
}

func mac(secret string, unix int64, body []byte) []byte {
	h := hmac.New(sha256.New, []byte(secret))
	h.Write([]byte(strconv.FormatInt(unix, 10)))
	h.Write([]byte("."))
	h.Write(body)
	return h.Sum(nil)
}

package webhook

import (
	"errors"
	"strconv"
	"testing"
	"time"
)

func TestSignVerify(t *testing.T) {
	now := time.Unix(1_800_000_000, 0)
	body := []byte(`{"reference":"delivery-1","status":"delivered"}`)
	sig := Sign("secret", now, body)
	ts := strconv.FormatInt(now.Unix(), 10)

	if err := Verify("secret", sig, ts, body, now.Add(time.Minute)); err != nil {
		t.Fatalf("valid signature rejected: %v", err)
	}
	cases := []struct {
		name          string
		secret, sig   string
		ts            string
		body          []byte
		now           time.Time
		want          error
	}{
		{"wrong secret", "other", sig, ts, body, now, ErrMismatch},
		{"tampered body", "secret", sig, ts, []byte(`{"reference":"delivery-1","status":"undelivered"}`), now, ErrMismatch},
		{"replayed with new timestamp", "secret", sig, strconv.FormatInt(now.Unix()+60, 10), body, now, ErrMismatch},
		{"too old", "secret", sig, ts, body, now.Add(6 * time.Minute), ErrStale},
		{"from the future", "secret", sig, ts, body, now.Add(-6 * time.Minute), ErrStale},
		{"missing", "secret", "", ts, body, now, ErrMissing},
		{"no prefix", "secret", sig[len("sha256="):], ts, body, now, ErrBadFormat},
		{"bad timestamp", "secret", sig, "yesterday", body, now, ErrBadFormat},
	}
	for _, c := range cases {
		if err := Verify(c.secret, c.sig, c.ts, c.body, c.now); !errors.Is(err, c.want) {
			t.Errorf("%s: err = %v, want %v", c.name, err, c.want)
		}
	}
}

// Package mockprovider is a fake SMS/email provider that misbehaves on purpose,
// so the app's retry, rate-limit and idempotency logic can be tested.
//
// API (JSON):
//
//	POST /v1/messages/sms    {"to": "+905...", "body": "...", "reference": "..."}
//	POST /v1/messages/email  {"to": "a@b.c", "subject": "...", "body": "...", "reference": "..."}
//	    Idempotency-Key header required. 202 {"message_id": "..."}.
//	    A repeated key returns the first acceptance again (200), so retries never
//	    send twice.
//	GET  /stats   counters for tests and demos
//	GET  /healthz
//
// After accepting a message it POSTs a signed delivery receipt to WebhookURL:
// {"message_id", "reference", "channel", "status": "delivered"|"undelivered", "timestamp"}.
package mockprovider

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log/slog"
	mrand "math/rand/v2"
	"net/http"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"

	"golang.org/x/time/rate"

	"campaign-composer/internal/webhook"
)

// Config sets how badly the provider behaves. Rates are probabilities (0..1).
type Config struct {
	ErrorRate     float64 // 500 Internal Server Error
	RateLimitRate float64 // 429 with Retry-After, on top of MaxRPS
	DropRate      float64 // accept the message, then answer 502 as if the response was lost
	SlowRate      float64 // answer after SlowLatency
	MaxRPS        int     // per channel; above it, 429. 0 means no limit.

	LatencyMin, LatencyMax time.Duration
	SlowLatency            time.Duration

	WebhookURL       string
	WebhookSecret    string
	DeliveredRate    float64 // share of receipts that say delivered; the rest undelivered
	WebhookDelayMin  time.Duration
	WebhookDelayMax  time.Duration
	WebhookDupRate   float64 // send the receipt twice
	WebhookEarlyRate float64 // send the receipt before answering the send request

	Seed uint64
}

type Stats struct {
	Accepted        int `json:"accepted"`
	Replays         int `json:"idempotent_replays"`
	Invalid         int `json:"rejected_invalid"`
	RateLimited     int `json:"rate_limited"`
	ServerErrors    int `json:"server_errors"`
	Dropped         int `json:"dropped_responses"`
	WebhooksSent    int `json:"webhooks_sent"`
	WebhooksFailed  int `json:"webhooks_failed"`
	DuplicateAccept int `json:"duplicate_references"` // same reference accepted under two keys: an app bug
}

type acceptance struct {
	MessageID string `json:"message_id"`
	Status    string `json:"status"`
}

type Provider struct {
	cfg    Config
	log    *slog.Logger
	client *http.Client

	mu         sync.Mutex
	rng        *mrand.Rand
	accepted   map[string]acceptance // idempotency key -> first acceptance
	references map[string]int        // reference -> acceptances (should never exceed 1)
	stats      Stats
	limiters   map[string]*rate.Limiter

	webhooks sync.WaitGroup
	ctx      context.Context
	stop     context.CancelFunc
}

func New(cfg Config, log *slog.Logger) *Provider {
	if cfg.DeliveredRate == 0 {
		cfg.DeliveredRate = 0.95
	}
	ctx, stop := context.WithCancel(context.Background())
	p := &Provider{
		cfg: cfg, log: log, client: &http.Client{Timeout: 5 * time.Second},
		rng:      mrand.New(mrand.NewPCG(cfg.Seed, cfg.Seed^0xabcdef)),
		accepted: map[string]acceptance{}, references: map[string]int{}, limiters: map[string]*rate.Limiter{},
		ctx: ctx, stop: stop,
	}
	if cfg.MaxRPS > 0 {
		for _, ch := range []string{"sms", "email"} {
			p.limiters[ch] = rate.NewLimiter(rate.Limit(cfg.MaxRPS), cfg.MaxRPS)
		}
	}
	return p
}

// Close stops sending receipts and waits for those in flight.
func (p *Provider) Close() {
	p.stop()
	p.webhooks.Wait()
}

func (p *Provider) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/messages/{channel}", p.handleSend)
	mux.HandleFunc("GET /stats", func(w http.ResponseWriter, r *http.Request) { writeJSON(w, 200, p.Stats()) })
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { writeJSON(w, 200, map[string]string{"status": "ok"}) })
	return mux
}

func (p *Provider) Stats() Stats {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.stats
}

// Accepted returns how many times each reference was accepted. Tests use it to
// prove every message was sent exactly once.
func (p *Provider) Accepted() map[string]int {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make(map[string]int, len(p.references))
	for k, v := range p.references {
		out[k] = v
	}
	return out
}

type sendRequest struct {
	To        string `json:"to"`
	Subject   string `json:"subject"`
	Body      string `json:"body"`
	Reference string `json:"reference"`
}

var (
	phoneRe = regexp.MustCompile(`^\+[1-9][0-9]{9,14}$`)
	emailRe = regexp.MustCompile(`^[^@\s]+@[^@\s]+\.[^@\s]+$`)
)

func (p *Provider) handleSend(w http.ResponseWriter, r *http.Request) {
	channel := r.PathValue("channel")
	if channel != "sms" && channel != "email" {
		writeError(w, 404, "unknown_channel")
		return
	}
	p.sleep(p.latency())

	key := r.Header.Get("Idempotency-Key")
	if key == "" {
		writeError(w, 400, "missing_idempotency_key")
		return
	}
	p.mu.Lock()
	if prev, ok := p.accepted[key]; ok {
		p.stats.Replays++
		p.mu.Unlock()
		writeJSON(w, 200, prev) // a retry of something already accepted: same answer, nothing sent
		return
	}
	p.mu.Unlock()

	var req sendRequest
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 64<<10)).Decode(&req); err != nil || req.Reference == "" || req.Body == "" {
		p.count(func(s *Stats) { s.Invalid++ })
		writeError(w, 400, "invalid_request")
		return
	}
	valid := phoneRe.MatchString(req.To)
	if channel == "email" {
		valid = emailRe.MatchString(req.To) && req.Subject != ""
	}
	if !valid {
		p.count(func(s *Stats) { s.Invalid++ })
		writeError(w, 400, "invalid_recipient")
		return
	}

	if l := p.limiters[channel]; l != nil && !l.Allow() {
		p.count(func(s *Stats) { s.RateLimited++ })
		w.Header().Set("Retry-After", "1")
		writeError(w, 429, "rate_limited")
		return
	}
	switch roll := p.roll(); {
	case roll < p.cfg.RateLimitRate:
		p.count(func(s *Stats) { s.RateLimited++ })
		w.Header().Set("Retry-After", strconv.Itoa(1+p.intN(2)))
		writeError(w, 429, "rate_limited")
		return
	case roll < p.cfg.RateLimitRate+p.cfg.ErrorRate:
		p.count(func(s *Stats) { s.ServerErrors++ })
		writeError(w, 500, "internal_error")
		return
	}

	acc := acceptance{MessageID: "msg_" + randomHex(8), Status: "accepted"}
	p.mu.Lock()
	if prev, ok := p.accepted[key]; ok { // a concurrent retry with the same key won the race
		p.stats.Replays++
		p.mu.Unlock()
		writeJSON(w, 200, prev)
		return
	}
	p.accepted[key] = acc
	p.references[req.Reference]++
	if p.references[req.Reference] > 1 {
		p.stats.DuplicateAccept++
	}
	p.stats.Accepted++
	early := p.rng.Float64() < p.cfg.WebhookEarlyRate
	drop := p.rng.Float64() < p.cfg.DropRate
	p.mu.Unlock()

	p.scheduleReceipt(acc.MessageID, req.Reference, channel, early)
	if drop {
		p.count(func(s *Stats) { s.Dropped++ })
		writeError(w, 502, "upstream_connection_reset") // accepted, but the client never learns it
		return
	}
	writeJSON(w, 202, acc)
}

type receipt struct {
	MessageID string    `json:"message_id"`
	Reference string    `json:"reference"`
	Channel   string    `json:"channel"`
	Status    string    `json:"status"`
	Timestamp time.Time `json:"timestamp"`
}

func (p *Provider) scheduleReceipt(messageID, reference, channel string, early bool) {
	if p.cfg.WebhookURL == "" {
		return
	}
	p.mu.Lock()
	status := "delivered"
	if p.rng.Float64() >= p.cfg.DeliveredRate {
		status = "undelivered"
	}
	delay := time.Duration(0)
	if !early {
		delay = p.cfg.WebhookDelayMin
		if span := p.cfg.WebhookDelayMax - p.cfg.WebhookDelayMin; span > 0 {
			delay += time.Duration(p.rng.Int64N(int64(span)))
		}
	}
	copies := 1
	if p.rng.Float64() < p.cfg.WebhookDupRate {
		copies = 2
	}
	p.mu.Unlock()

	body, _ := json.Marshal(receipt{MessageID: messageID, Reference: reference, Channel: channel, Status: status, Timestamp: time.Now().UTC()})
	p.webhooks.Add(1)
	go func() {
		defer p.webhooks.Done()
		select {
		case <-p.ctx.Done():
			return
		case <-time.After(delay):
		}
		for range copies {
			p.postReceipt(body)
		}
	}()
}

// postReceipt delivers one receipt, retrying with backoff like real providers.
func (p *Provider) postReceipt(body []byte) {
	wait := 200 * time.Millisecond
	for attempt := 1; attempt <= 4; attempt++ {
		now := time.Now()
		req, _ := http.NewRequestWithContext(p.ctx, http.MethodPost, p.cfg.WebhookURL, bytes.NewReader(body))
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set(webhook.TimestampHeader, strconv.FormatInt(now.Unix(), 10))
		req.Header.Set(webhook.SignatureHeader, webhook.Sign(p.cfg.WebhookSecret, now, body))
		resp, err := p.client.Do(req)
		if err == nil {
			resp.Body.Close()
			if resp.StatusCode < 300 {
				p.count(func(s *Stats) { s.WebhooksSent++ })
				return
			}
		}
		select {
		case <-p.ctx.Done():
			return
		case <-time.After(wait):
		}
		wait *= 2
	}
	p.count(func(s *Stats) { s.WebhooksFailed++ })
	p.log.Warn("delivery receipt could not be delivered", "url", p.cfg.WebhookURL)
}

func (p *Provider) latency() time.Duration {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.rng.Float64() < p.cfg.SlowRate {
		return p.cfg.SlowLatency
	}
	d := p.cfg.LatencyMin
	if span := p.cfg.LatencyMax - p.cfg.LatencyMin; span > 0 {
		d += time.Duration(p.rng.Int64N(int64(span)))
	}
	return d
}

func (p *Provider) sleep(d time.Duration) {
	if d > 0 {
		time.Sleep(d)
	}
}

func (p *Provider) roll() float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.rng.Float64()
}

func (p *Provider) intN(n int) int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.rng.IntN(n)
}

func (p *Provider) count(f func(*Stats)) {
	p.mu.Lock()
	f(&p.stats)
	p.mu.Unlock()
}

func randomHex(n int) string {
	b := make([]byte, n)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code string) {
	writeJSON(w, status, map[string]string{"error": code, "message": strings.ReplaceAll(code, "_", " ")})
}

// String summarises the configuration for the startup log.
func (c Config) String() string {
	return fmt.Sprintf("errors=%.0f%% 429s=%.0f%% drops=%.0f%% slow=%.0f%% max_rps=%d latency=%s-%s receipts=%s",
		c.ErrorRate*100, c.RateLimitRate*100, c.DropRate*100, c.SlowRate*100, c.MaxRPS, c.LatencyMin, c.LatencyMax, c.WebhookURL)
}

package mockprovider

import (
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"campaign-composer/internal/webhook"
)

var quiet = slog.New(slog.NewTextHandler(io.Discard, nil))

func start(t *testing.T, cfg Config) (*Provider, string) {
	t.Helper()
	p := New(cfg, quiet)
	ts := httptest.NewServer(p.Handler())
	t.Cleanup(func() { ts.Close(); p.Close() })
	return p, ts.URL
}

func send(t *testing.T, base, channel, key, body string) (int, map[string]any, http.Header) {
	t.Helper()
	req, _ := http.NewRequest("POST", base+"/v1/messages/"+channel, strings.NewReader(body))
	if key != "" {
		req.Header.Set("Idempotency-Key", key)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var out map[string]any
	json.NewDecoder(resp.Body).Decode(&out)
	return resp.StatusCode, out, resp.Header
}

const smsBody = `{"to":"+905321234567","body":"Merhaba","reference":"delivery-1"}`

func TestAcceptAndIdempotentReplay(t *testing.T) {
	p, url := start(t, Config{})
	status, first, _ := send(t, url, "sms", "k1", smsBody)
	if status != 202 || first["message_id"] == "" {
		t.Fatalf("first send: %d %v", status, first)
	}
	status, again, _ := send(t, url, "sms", "k1", smsBody)
	if status != 200 || again["message_id"] != first["message_id"] {
		t.Fatalf("replay: %d %v, want the first acceptance again", status, again)
	}
	if s := p.Stats(); s.Accepted != 1 || s.Replays != 1 || p.Accepted()["delivery-1"] != 1 {
		t.Fatalf("stats = %+v", s)
	}
}

func TestRejectsBadRequests(t *testing.T) {
	_, url := start(t, Config{})
	cases := []struct {
		channel, key, body, code string
		status                   int
	}{
		{"sms", "", smsBody, "missing_idempotency_key", 400},
		{"sms", "a", `{"to":"+90555","body":"x","reference":"r"}`, "invalid_recipient", 400},
		{"email", "b", `{"to":"no-at-sign.example.com","subject":"s","body":"x","reference":"r"}`, "invalid_recipient", 400},
		{"email", "c", `{"to":"a@example.com","body":"x","reference":"r"}`, "invalid_recipient", 400}, // no subject
		{"fax", "d", smsBody, "unknown_channel", 404},
	}
	for _, c := range cases {
		status, body, _ := send(t, url, c.channel, c.key, c.body)
		if status != c.status || body["error"] != c.code {
			t.Errorf("%s %s: %d %v, want %d %s", c.channel, c.body, status, body, c.status, c.code)
		}
	}
}

func TestChaos(t *testing.T) {
	_, url := start(t, Config{ErrorRate: 1})
	if status, _, _ := send(t, url, "sms", "e", smsBody); status != 500 {
		t.Errorf("error rate 1: status %d", status)
	}
	_, url = start(t, Config{RateLimitRate: 1})
	status, _, h := send(t, url, "sms", "r", smsBody)
	if status != 429 || h.Get("Retry-After") == "" {
		t.Errorf("429 rate 1: status %d, Retry-After %q", status, h.Get("Retry-After"))
	}
}

func TestDroppedResponseIsReplayed(t *testing.T) {
	p, url := start(t, Config{DropRate: 1})
	status, _, _ := send(t, url, "sms", "k", smsBody)
	if status != 502 {
		t.Fatalf("drop: status %d", status)
	}
	// The client retries with the same key: it learns the message was accepted.
	status, body, _ := send(t, url, "sms", "k", smsBody)
	if status != 200 || body["message_id"] == "" || p.Accepted()["delivery-1"] != 1 {
		t.Fatalf("retry after drop: %d %v accepted=%d", status, body, p.Accepted()["delivery-1"])
	}
}

func TestMaxRPS(t *testing.T) {
	_, url := start(t, Config{MaxRPS: 5})
	limited := 0
	for i := range 20 {
		if status, _, _ := send(t, url, "email", "k"+string(rune('a'+i)),
			`{"to":"a@example.com","subject":"s","body":"x","reference":"r`+string(rune('a'+i))+`"}`); status == 429 {
			limited++
		}
	}
	if limited < 10 {
		t.Fatalf("only %d of 20 instant requests were limited at 5 rps", limited)
	}
}

func TestSignedReceipts(t *testing.T) {
	var mu sync.Mutex
	var got []receipt
	hook := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		if err := webhook.Verify("s3cret", r.Header.Get(webhook.SignatureHeader), r.Header.Get(webhook.TimestampHeader), body, time.Now()); err != nil {
			t.Errorf("receipt signature: %v", err)
			w.WriteHeader(401)
			return
		}
		var rc receipt
		json.Unmarshal(body, &rc)
		mu.Lock()
		got = append(got, rc)
		mu.Unlock()
	}))
	defer hook.Close()

	_, url := start(t, Config{WebhookURL: hook.URL, WebhookSecret: "s3cret", DeliveredRate: 1, WebhookDupRate: 1})
	_, acc, _ := send(t, url, "sms", "k", smsBody)

	deadline := time.Now().Add(3 * time.Second)
	for {
		mu.Lock()
		n := len(got)
		mu.Unlock()
		if n == 2 || time.Now().After(deadline) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	mu.Lock()
	defer mu.Unlock()
	if len(got) != 2 { // duplicate rate 1: the same receipt twice
		t.Fatalf("got %d receipts, want 2", len(got))
	}
	if got[0].MessageID != acc["message_id"] || got[0].Reference != "delivery-1" || got[0].Status != "delivered" || got[0] != got[1] {
		t.Fatalf("receipts = %+v", got)
	}
}

// Command mockprovider runs the fake SMS/email provider. Every misbehaviour is
// set with an environment variable; see internal/mockprovider.
package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"campaign-composer/internal/mockprovider"
)

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	cfg := mockprovider.Config{
		ErrorRate:        envFloat("MOCK_ERROR_RATE", 0.05),
		RateLimitRate:    envFloat("MOCK_RATE_LIMIT_RATE", 0.05),
		DropRate:         envFloat("MOCK_DROP_RATE", 0.01),
		SlowRate:         envFloat("MOCK_SLOW_RATE", 0.02),
		MaxRPS:           int(envFloat("MOCK_MAX_RPS", 150)),
		LatencyMin:       envDuration("MOCK_LATENCY_MIN", 50*time.Millisecond),
		LatencyMax:       envDuration("MOCK_LATENCY_MAX", 500*time.Millisecond),
		SlowLatency:      envDuration("MOCK_SLOW_LATENCY", 3*time.Second),
		WebhookURL:       os.Getenv("WEBHOOK_URL"),
		WebhookSecret:    os.Getenv("WEBHOOK_SECRET"),
		DeliveredRate:    envFloat("MOCK_DELIVERED_RATE", 0.95),
		WebhookDelayMin:  envDuration("MOCK_RECEIPT_DELAY_MIN", 500*time.Millisecond),
		WebhookDelayMax:  envDuration("MOCK_RECEIPT_DELAY_MAX", 5*time.Second),
		WebhookDupRate:   envFloat("MOCK_RECEIPT_DUPLICATE_RATE", 0.05),
		WebhookEarlyRate: envFloat("MOCK_RECEIPT_EARLY_RATE", 0.02),
		Seed:             uint64(time.Now().UnixNano()),
	}
	if cfg.WebhookURL != "" && cfg.WebhookSecret == "" {
		log.Error("WEBHOOK_SECRET is required when WEBHOOK_URL is set")
		os.Exit(1)
	}

	p := mockprovider.New(cfg, log)
	srv := &http.Server{Addr: ":" + env("PORT", "9090"), Handler: p.Handler(), ReadHeaderTimeout: 10 * time.Second}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		log.Info("mock provider listening", "addr", srv.Addr, "config", cfg.String())
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("listen", "error", err)
			stop()
		}
	}()
	<-ctx.Done()
	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	srv.Shutdown(shutdown)
	p.Close()
}

func env(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func envFloat(key string, def float64) float64 {
	if f, err := strconv.ParseFloat(os.Getenv(key), 64); err == nil {
		return f
	}
	return def
}

func envDuration(key string, def time.Duration) time.Duration {
	if d, err := time.ParseDuration(os.Getenv(key)); err == nil {
		return d
	}
	return def
}

// Package delivery sends approved campaign messages through the provider:
// queue workers, per-channel rate limits, retries and delivery receipts.
package delivery

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"time"
)

// Message is one message to one recipient.
type Message struct {
	Channel   string `json:"-"`
	To        string `json:"to"`
	Subject   string `json:"subject,omitempty"`
	Body      string `json:"body"`
	Reference string `json:"reference"` // our delivery ID; receipts carry it back
	// IdempotencyKey makes a retried send safe: the provider answers a repeated
	// key with its first result instead of sending again.
	IdempotencyKey string `json:"-"`
}

// ProviderError is a failed send. Temporary errors are retried.
type ProviderError struct {
	StatusCode int // 0 for a network error or timeout
	Code       string
	RetryAfter time.Duration
}

func (e *ProviderError) Error() string {
	if e.StatusCode == 0 {
		return "provider unreachable: " + e.Code
	}
	return fmt.Sprintf("provider returned HTTP %d (%s)", e.StatusCode, e.Code)
}

// Temporary reports whether retrying may succeed: rate limits, server errors and
// network problems. Other 4xx answers (e.g. an invalid number) will not change.
func (e *ProviderError) Temporary() bool {
	return e.StatusCode == 0 || e.StatusCode == http.StatusTooManyRequests ||
		e.StatusCode == http.StatusRequestTimeout || e.StatusCode >= 500
}

// Provider sends one message and returns the provider's message ID.
type Provider interface {
	Send(ctx context.Context, m Message) (messageID string, err error)
}

// Client talks to the provider's HTTP API.
type Client struct {
	BaseURL string
	HTTP    *http.Client
}

func NewClient(baseURL string) *Client {
	return &Client{BaseURL: baseURL, HTTP: &http.Client{Timeout: 10 * time.Second}}
}

func (c *Client) Send(ctx context.Context, m Message) (string, error) {
	body, _ := json.Marshal(m)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.BaseURL+"/v1/messages/"+m.Channel, bytes.NewReader(body))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Idempotency-Key", m.IdempotencyKey)
	resp, err := c.HTTP.Do(req)
	if err != nil {
		return "", &ProviderError{Code: err.Error()}
	}
	defer resp.Body.Close()
	var out struct {
		MessageID string `json:"message_id"`
		Error     string `json:"error"`
	}
	_ = json.NewDecoder(resp.Body).Decode(&out)
	if resp.StatusCode >= 300 {
		pe := &ProviderError{StatusCode: resp.StatusCode, Code: out.Error}
		if s, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && s >= 0 {
			pe.RetryAfter = time.Duration(s) * time.Second
		}
		return "", pe
	}
	if out.MessageID == "" {
		return "", &ProviderError{StatusCode: resp.StatusCode, Code: "missing message_id"}
	}
	return out.MessageID, nil
}

package delivery

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"strconv"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/time/rate"

	"campaign-composer/internal/events"
	"campaign-composer/internal/message"
	"campaign-composer/internal/queue"
)

const (
	StatusQueued      = "queued"
	StatusSending     = "sending"
	StatusRetrying    = "retrying"
	StatusSent        = "sent"
	StatusDelivered   = "delivered"
	StatusUndelivered = "undelivered"
	StatusFailed      = "failed"
)

// Channels and their queue job kinds.
var Channels = []string{"sms", "email"}

func JobKind(channel string) string { return "send_" + channel }

// Topic must match campaign.Topic; it is repeated here to keep the packages apart.
func campaignTopic(id string) string { return "campaign:" + id }

// Observer receives delivery outcomes for metrics. Nil is fine.
type Observer interface {
	ProviderCall(channel string, status int, d time.Duration)
	DeliveryFinished(channel, status string)
}

type Sender struct {
	pool     *pgxpool.Pool
	provider Provider
	log      *slog.Logger
	limiters map[string]*rate.Limiter
	ringer   *ringer
	observer Observer
}

// NewSender limits each channel to perSecond sends. The burst is 1, so the
// limit also holds over any short window, not only on average.
func NewSender(pool *pgxpool.Pool, provider Provider, perSecond float64, log *slog.Logger, obs Observer) *Sender {
	s := &Sender{pool: pool, provider: provider, log: log, limiters: map[string]*rate.Limiter{},
		ringer: newRinger(pool, 250*time.Millisecond), observer: obs}
	for _, ch := range Channels {
		s.limiters[ch] = rate.NewLimiter(rate.Limit(perSecond), 1)
	}
	return s
}

type jobPayload struct {
	DeliveryID int64 `json:"delivery_id"`
}

// Handle sends one delivery. It is the queue handler for both channels.
func (s *Sender) Handle(ctx context.Context, job queue.Job) error {
	var p jobPayload
	if err := json.Unmarshal(job.Payload, &p); err != nil {
		return queue.Permanent(err)
	}
	var (
		status, channel, campaignID string
		r                           message.Recipient
		phone, email                string
		content                     message.Content
	)
	err := s.pool.QueryRow(ctx, `
		SELECT d.status, d.channel, d.campaign_id::text,
		       u.first_name, u.last_name, u.city, u.phone, u.email,
		       c.sms_body, c.email_subject, c.email_body
		FROM deliveries d
		JOIN users u ON u.id = d.user_id
		JOIN campaigns c ON c.id = d.campaign_id
		WHERE d.id = $1`, p.DeliveryID).Scan(&status, &channel, &campaignID,
		&r.FirstName, &r.LastName, &r.City, &phone, &email,
		&content.SMS, &content.EmailSubject, &content.EmailBody)
	if err != nil {
		return err
	}
	switch status {
	case StatusSent, StatusDelivered, StatusUndelivered, StatusFailed:
		return nil // already finished: a duplicate job must not send again
	}
	if _, err := s.pool.Exec(ctx, `
		UPDATE deliveries SET status = 'sending', attempts = attempts + 1, updated_at = now()
		WHERE id = $1 AND status IN ('queued', 'retrying', 'sending')`, p.DeliveryID); err != nil {
		return err
	}
	s.ringer.ring(campaignTopic(campaignID))

	m := Message{Channel: channel, Reference: strconv.FormatInt(p.DeliveryID, 10),
		IdempotencyKey: fmt.Sprintf("delivery-%d", p.DeliveryID)}
	if channel == "sms" {
		m.To, m.Body = phone, message.Render(content.SMS, r)
	} else {
		m.To, m.Subject, m.Body = email, message.Render(content.EmailSubject, r), message.Render(content.EmailBody, r)
	}

	if err := s.limiters[channel].Wait(ctx); err != nil {
		return err // the job timed out waiting its turn; it will be retried
	}
	start := time.Now()
	msgID, err := s.provider.Send(ctx, m)
	s.observe(channel, err, time.Since(start))

	if err == nil {
		// A receipt may already have arrived (it can beat the response): keep it.
		_, err = s.pool.Exec(ctx, `
			UPDATE deliveries SET
				status = CASE WHEN status IN ('delivered', 'undelivered') THEN status ELSE 'sent' END,
				provider_message_id = $2, sent_at = now(), last_error = '', updated_at = now()
			WHERE id = $1`, p.DeliveryID, msgID)
		if err != nil {
			return err
		}
		s.finished(ctx, campaignID, channel, StatusSent)
		return nil
	}

	var pe *ProviderError
	if errors.As(err, &pe) && !pe.Temporary() {
		s.markFailed(ctx, p.DeliveryID, campaignID, channel, err)
		return queue.Permanent(err)
	}
	if _, uerr := s.pool.Exec(ctx, `
		UPDATE deliveries SET status = 'retrying', last_error = $2, updated_at = now()
		WHERE id = $1 AND status = 'sending'`, p.DeliveryID, err.Error()); uerr != nil {
		s.log.Error("mark delivery retrying", "delivery", p.DeliveryID, "error", uerr)
	}
	s.ringer.ring(campaignTopic(campaignID))
	if pe != nil && pe.RetryAfter > 0 {
		return queue.RetryAfter(err, pe.RetryAfter)
	}
	return err
}

// OnFailed marks a delivery failed once the queue has given up on it.
func (s *Sender) OnFailed(ctx context.Context, job queue.Job, err error) {
	var p jobPayload
	if json.Unmarshal(job.Payload, &p) != nil {
		return
	}
	var campaignID, channel string
	if s.pool.QueryRow(ctx, `SELECT campaign_id::text, channel FROM deliveries WHERE id = $1`, p.DeliveryID).
		Scan(&campaignID, &channel) != nil {
		return
	}
	s.markFailed(ctx, p.DeliveryID, campaignID, channel, err)
}

func (s *Sender) markFailed(ctx context.Context, id int64, campaignID, channel string, cause error) {
	// A receipt that already said delivered wins over our own give-up: the
	// provider knows best whether the message arrived.
	tag, err := s.pool.Exec(ctx, `
		UPDATE deliveries SET status = 'failed', last_error = $2, updated_at = now()
		WHERE id = $1 AND status NOT IN ('sent', 'delivered', 'undelivered')`, id, cause.Error())
	if err != nil {
		s.log.Error("mark delivery failed", "delivery", id, "error", err)
		return
	}
	if tag.RowsAffected() == 1 {
		s.finished(ctx, campaignID, channel, StatusFailed)
	}
}

// finished records a delivery leaving the send pipeline and completes the
// campaign once none are left in it.
func (s *Sender) finished(ctx context.Context, campaignID, channel, status string) {
	if s.observer != nil {
		s.observer.DeliveryFinished(channel, status)
	}
	s.ringer.ring(campaignTopic(campaignID))
	if err := CompleteIfDone(ctx, s.pool, campaignID); err != nil {
		s.log.Error("complete campaign", "campaign", campaignID, "error", err)
	}
}

func (s *Sender) observe(channel string, err error, d time.Duration) {
	if s.observer == nil {
		return
	}
	status := 202
	var pe *ProviderError
	if errors.As(err, &pe) {
		status = pe.StatusCode
	} else if err != nil {
		status = 0
	}
	s.observer.ProviderCall(channel, status, d)
}

// CompleteIfDone moves a sending campaign to completed when none of its
// deliveries are still queued, sending or retrying. Receipts may still arrive
// afterwards; they update deliveries, not the campaign's status.
func CompleteIfDone(ctx context.Context, pool *pgxpool.Pool, campaignID string) error {
	var done bool
	err := pool.QueryRow(ctx, `
		WITH done AS (
			UPDATE campaigns SET status = 'completed', completed_at = now(), updated_at = now()
			WHERE id = $1 AND status = 'sending'
			  AND NOT EXISTS (SELECT 1 FROM deliveries
			                  WHERE campaign_id = $1 AND status IN ('queued', 'sending', 'retrying'))
			RETURNING id)
		SELECT EXISTS (SELECT 1 FROM done)`, campaignID).Scan(&done)
	if err != nil || !done {
		return err
	}
	_, err = events.Add(ctx, pool, campaignTopic(campaignID), "completed", map[string]string{"status": "completed"})
	return err
}

// ringer limits doorbells per topic to one every `every`, with a trailing ring
// so the last change is never lost. Thousands of deliveries then cost a few
// notifications a second, not one each.
type ringer struct {
	pool  *pgxpool.Pool
	every time.Duration

	mu      sync.Mutex
	last    map[string]time.Time
	pending map[string]bool
}

func newRinger(pool *pgxpool.Pool, every time.Duration) *ringer {
	return &ringer{pool: pool, every: every, last: map[string]time.Time{}, pending: map[string]bool{}}
}

func (r *ringer) ring(topic string) {
	r.mu.Lock()
	if r.pending[topic] {
		r.mu.Unlock()
		return
	}
	since := time.Since(r.last[topic])
	if since >= r.every {
		r.last[topic] = time.Now()
		r.mu.Unlock()
		r.send(topic)
		return
	}
	r.pending[topic] = true
	r.mu.Unlock()
	time.AfterFunc(r.every-since, func() {
		r.mu.Lock()
		r.pending[topic] = false
		r.last[topic] = time.Now()
		r.mu.Unlock()
		r.send(topic)
	})
}

func (r *ringer) send(topic string) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = events.Ring(ctx, r.pool, topic)
}

package campaign

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"

	"campaign-composer/internal/delivery"
	"campaign-composer/internal/events"
	"campaign-composer/internal/message"
	"campaign-composer/internal/queue"
	"campaign-composer/internal/segment"
)

// deliveryMaxAttempts bounds retries per message: with backoff (1 s base, 60 s
// cap) a message keeps trying for about two minutes before it counts as failed.
const deliveryMaxAttempts = 6

// consentColumn is fixed per channel; it never comes from input.
var consentColumn = map[string]string{"sms": "sms_consent", "email": "email_consent"}

// ErrNotReady means the campaign has no valid messages yet.
var ErrNotReady = errors.New("the campaign needs an audience and valid messages before approval")

type ApproveResult struct {
	Campaign Campaign `json:"campaign"`
	SMS      int      `json:"sms"`
	Email    int      `json:"email"`
}

// Approve freezes the campaign and queues one delivery per consenting
// recipient and channel. Everything happens in one transaction: the deliveries,
// their send jobs and the status change commit together or not at all.
func (s *Service) Approve(ctx context.Context, id string) (ApproveResult, error) {
	var res ApproveResult
	err := pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		c, err := scan(tx.QueryRow(ctx, selectCampaign+` WHERE id = $1 FOR UPDATE`, id))
		if err != nil {
			return err
		}
		if c.Status != StatusContentReady {
			if c.Status == StatusSending || c.Status == StatusCompleted || c.Status == StatusApproved {
				return ErrWrongStatus // already approved: approving again does nothing
			}
			return ErrNotReady
		}
		if c.ContentState != ContentReady || c.Rule == nil || c.Language == nil {
			return ErrNotReady
		}

		// Check the messages once more against the audience as it is now:
		// "within 30 days" rules shift as time passes.
		longest, err := s.longest(ctx, tx, *c.Rule)
		if err != nil {
			return err
		}
		if _, problems := message.Validate(message.Content{Language: *c.Language, SMS: c.SMS,
			EmailSubject: c.EmailSubject, EmailBody: c.EmailBody}, longest); len(problems) > 0 {
			return &ContentError{Problems: problems}
		}

		q, err := segment.Compile(*c.Rule, s.now())
		if err != nil {
			return err
		}
		q = q.WithOffset(1) // $1 is the campaign ID
		args := append([]any{id}, q.Args...)
		for _, ch := range delivery.Channels {
			// ch and its consent column come from fixed lists, never from input.
			if _, err := tx.Exec(ctx, `
				INSERT INTO deliveries (campaign_id, user_id, channel)
				SELECT $1, u.id, '`+ch+`' FROM users u
				WHERE `+q.Where+` AND u.`+consentColumn[ch]+`
				ON CONFLICT (campaign_id, user_id, channel) DO NOTHING`, args...); err != nil {
				return err
			}
		}
		// One send job per delivery, keyed by the delivery so it can never be
		// queued twice.
		if _, err := tx.Exec(ctx, `
			INSERT INTO jobs (kind, dedup_key, payload, max_attempts)
			SELECT 'send_' || d.channel, 'delivery:' || d.id, jsonb_build_object('delivery_id', d.id), $2
			FROM deliveries d WHERE d.campaign_id = $1
			ON CONFLICT (dedup_key) DO NOTHING`, id, deliveryMaxAttempts); err != nil {
			return err
		}
		if err := tx.QueryRow(ctx, `
			SELECT count(*) FILTER (WHERE channel = 'sms'), count(*) FILTER (WHERE channel = 'email')
			FROM deliveries WHERE campaign_id = $1`, id).Scan(&res.SMS, &res.Email); err != nil {
			return err
		}

		status := StatusSending
		if res.SMS+res.Email == 0 {
			status = StatusCompleted // nobody to send to
		}
		if _, err := tx.Exec(ctx, `
			UPDATE campaigns SET status = $2, approved_at = now(), updated_at = now(),
				completed_at = CASE WHEN $2 = 'completed' THEN now() END
			WHERE id = $1`, id, status); err != nil {
			return err
		}
		for _, ch := range delivery.Channels {
			if err := events.Ring(ctx, tx, queue.Topic(delivery.JobKind(ch))); err != nil {
				return err
			}
		}
		_, err = events.Add(ctx, tx, Topic(id), "approved", map[string]int{"sms": res.SMS, "email": res.Email})
		return err
	})
	if err != nil {
		return ApproveResult{}, err
	}
	res.Campaign, err = s.Get(ctx, id)
	return res, err
}

// DeliveryCounts is how many deliveries a campaign has per channel and status.
type DeliveryCounts map[string]map[string]int

func (s *Service) DeliveryCounts(ctx context.Context, id string) (DeliveryCounts, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT channel, status, count(*) FROM deliveries WHERE campaign_id = $1 GROUP BY 1, 2`, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := DeliveryCounts{"sms": {}, "email": {}}
	for rows.Next() {
		var ch, st string
		var n int
		if err := rows.Scan(&ch, &st, &n); err != nil {
			return nil, err
		}
		out[ch][st] = n
	}
	return out, rows.Err()
}

type DeliveryRow struct {
	ID        int64  `json:"id"`
	Channel   string `json:"channel"`
	Status    string `json:"status"`
	Attempts  int    `json:"attempts"`
	LastError string `json:"last_error"`
	FirstName string `json:"first_name"`
	City      string `json:"city"`
}

// Deliveries lists a campaign's deliveries, optionally of one status, newest
// change first.
func (s *Service) Deliveries(ctx context.Context, id, status string, limit int) ([]DeliveryRow, error) {
	rows, err := s.pool.Query(ctx, `
		SELECT d.id, d.channel, d.status, d.attempts, d.last_error, u.first_name, u.city
		FROM deliveries d JOIN users u ON u.id = d.user_id
		WHERE d.campaign_id = $1 AND ($2 = '' OR d.status = $2)
		ORDER BY d.updated_at DESC, d.id LIMIT $3`, id, status, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []DeliveryRow{}
	for rows.Next() {
		var r DeliveryRow
		if err := rows.Scan(&r.ID, &r.Channel, &r.Status, &r.Attempts, &r.LastError, &r.FirstName, &r.City); err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

package delivery

import (
	"context"
	"errors"
	"strconv"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"campaign-composer/internal/store"
)

// Receipt is the provider's delivery report, sent to our webhook.
type Receipt struct {
	MessageID string    `json:"message_id"`
	Reference string    `json:"reference"` // our delivery ID
	Channel   string    `json:"channel"`
	Status    string    `json:"status"` // delivered | undelivered
	Timestamp time.Time `json:"timestamp"`
}

var ErrBadReceipt = errors.New("receipt has an unknown status or reference")

// ApplyReceipt records a receipt. It reports whether anything changed.
//
// Receipts arrive late, twice, or even before our send call has returned, so
// the update only moves forward: once a delivery is delivered or undelivered,
// later receipts change nothing. A receipt that says delivered also overrides
// our own "failed" (we gave up, but the provider had accepted the message and
// its answer was lost). The delivery is found by our reference, so a receipt
// that beats the send response still lands; the message ID must match if we
// already know it.
func ApplyReceipt(ctx context.Context, pool *pgxpool.Pool, r Receipt) (bool, error) {
	id, err := strconv.ParseInt(r.Reference, 10, 64)
	if err != nil || (r.Status != StatusDelivered && r.Status != StatusUndelivered) || r.MessageID == "" {
		return false, ErrBadReceipt
	}
	var campaignID string
	err = pool.QueryRow(ctx, `
		UPDATE deliveries SET status = $2, receipt_at = $3, updated_at = now(),
			provider_message_id = coalesce(provider_message_id, $4)
		WHERE id = $1 AND status NOT IN ('delivered', 'undelivered')
		  AND (provider_message_id IS NULL OR provider_message_id = $4)
		RETURNING campaign_id::text`, id, r.Status, r.Timestamp, r.MessageID).Scan(&campaignID)
	if errors.Is(store.MapErr(err), store.ErrNotFound) {
		return false, nil // duplicate, late, or not ours: nothing to do
	}
	if err != nil {
		return false, store.MapErr(err)
	}
	// The receipt may have finished a delivery that was still retrying.
	return true, CompleteIfDone(ctx, pool, campaignID)
}

package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"

	"campaign-composer/internal/campaign"
	"campaign-composer/internal/delivery"
	"campaign-composer/internal/events"
	"campaign-composer/internal/webhook"
)

func (s *Server) handleApprove(w http.ResponseWriter, r *http.Request) {
	res, err := s.campaigns.Approve(r.Context(), r.PathValue("id"))
	var ce *campaign.ContentError
	switch {
	case err == nil:
		writeJSON(w, http.StatusOK, res)
	case errors.As(err, &ce):
		writeProblems(w, http.StatusUnprocessableEntity, "invalid_content",
			"the messages no longer fit this audience; edit or regenerate them", ce.Problems)
	case errors.Is(err, campaign.ErrNotReady):
		writeError(w, http.StatusConflict, "not_ready", err.Error())
	case errors.Is(err, campaign.ErrWrongStatus):
		writeError(w, http.StatusConflict, "already_approved", "this campaign has already been approved")
	default:
		s.storeError(w, r, err, "campaign")
	}
}

func (s *Server) handleDeliveryCounts(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if _, err := s.campaigns.Get(r.Context(), id); err != nil {
		s.storeError(w, r, err, "campaign")
		return
	}
	counts, err := s.campaigns.DeliveryCounts(r.Context(), id)
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"counts": counts})
}

func (s *Server) handleListDeliveries(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if _, err := s.campaigns.Get(r.Context(), id); err != nil {
		s.storeError(w, r, err, "campaign")
		return
	}
	limit, err := strconv.Atoi(r.URL.Query().Get("limit"))
	if err != nil || limit <= 0 || limit > 200 {
		limit = 50
	}
	rows, err := s.campaigns.Deliveries(r.Context(), id, r.URL.Query().Get("status"), limit)
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"deliveries": rows})
}

// handleReceipt is the provider's webhook. The signature and timestamp are
// checked before the body is trusted. Unknown or duplicate receipts get 200, so
// the provider does not keep retrying them; database errors get 500, so it does.
func (s *Server) handleReceipt(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 64<<10))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "body too large")
		return
	}
	if err := webhook.Verify(s.webhookSecret, r.Header.Get(webhook.SignatureHeader),
		r.Header.Get(webhook.TimestampHeader), body, s.now()); err != nil {
		s.observe("webhook", "rejected")
		writeError(w, http.StatusUnauthorized, "invalid_signature", err.Error())
		return
	}
	var rc delivery.Receipt
	if err := json.Unmarshal(body, &rc); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid JSON")
		return
	}
	applied, err := delivery.ApplyReceipt(r.Context(), s.pool, rc)
	switch {
	case errors.Is(err, delivery.ErrBadReceipt):
		writeError(w, http.StatusBadRequest, "invalid_request", err.Error())
		return
	case err != nil:
		s.internalError(w, r, err)
		return
	}
	outcome := "ignored"
	if applied {
		outcome = "applied"
		var campaignID string
		if s.pool.QueryRow(r.Context(), `SELECT campaign_id::text FROM deliveries WHERE id = $1::bigint`, rc.Reference).Scan(&campaignID) == nil {
			events.Ring(r.Context(), s.pool, campaign.Topic(campaignID))
		}
	}
	s.observe("webhook", outcome)
	writeJSON(w, http.StatusOK, map[string]bool{"applied": applied})
}

func (s *Server) observe(kind, outcome string) {
	if s.metrics != nil {
		s.metrics.Webhook(outcome)
	}
}

