package campaign

import (
	"context"
	"time"
)

// Grid codes: one character per delivery, in delivery order. The dashboard
// draws one square per character, coloured by status.
var GridCodes = map[string]string{
	"queued": "q", "sending": "s", "retrying": "r", "sent": "t",
	"delivered": "d", "undelivered": "u", "failed": "f",
}

// Progress is a live picture of a campaign's sending.
type Progress struct {
	Status          string             `json:"status"`
	Counts          DeliveryCounts     `json:"counts"`
	Grid            map[string]string  `json:"grid"`
	Throughput      map[string]float64 `json:"throughput"` // accepted per second, last 5 s
	Retries         int                `json:"retries"`    // attempts beyond the first, all deliveries
	PendingReceipts int                `json:"pending_receipts"`
	CompletedAt     *time.Time         `json:"completed_at"`
}

const throughputWindow = 5 // seconds

// Progress reads the campaign's delivery state in one pass.
func (s *Service) Progress(ctx context.Context, id string) (Progress, error) {
	p := Progress{
		Counts:     DeliveryCounts{"sms": {}, "email": {}},
		Grid:       map[string]string{"sms": "", "email": ""},
		Throughput: map[string]float64{"sms": 0, "email": 0},
	}
	if err := s.pool.QueryRow(ctx, `SELECT status, completed_at FROM campaigns WHERE id = $1`, id).
		Scan(&p.Status, &p.CompletedAt); err != nil {
		return Progress{}, err
	}
	rows, err := s.pool.Query(ctx, `
		SELECT channel,
		       string_agg(CASE status
		           WHEN 'queued' THEN 'q' WHEN 'sending' THEN 's' WHEN 'retrying' THEN 'r'
		           WHEN 'sent' THEN 't' WHEN 'delivered' THEN 'd' WHEN 'undelivered' THEN 'u'
		           ELSE 'f' END, '' ORDER BY id),
		       count(*) FILTER (WHERE sent_at > now() - make_interval(secs => $2)),
		       coalesce(sum(greatest(attempts - 1, 0)), 0)
		FROM deliveries WHERE campaign_id = $1 GROUP BY channel`, id, throughputWindow)
	if err != nil {
		return Progress{}, err
	}
	defer rows.Close()
	statusOf := map[rune]string{}
	for st, code := range GridCodes {
		statusOf[rune(code[0])] = st
	}
	for rows.Next() {
		var ch, grid string
		var recent, retries int
		if err := rows.Scan(&ch, &grid, &recent, &retries); err != nil {
			return Progress{}, err
		}
		p.Grid[ch] = grid
		p.Throughput[ch] = float64(recent) / throughputWindow
		p.Retries += retries
		for _, c := range grid {
			p.Counts[ch][statusOf[c]]++
		}
		p.PendingReceipts += p.Counts[ch]["sent"]
	}
	return p, rows.Err()
}

// receiptGrace is how long the stream waits for receipts after sending ends.
const receiptGrace = 2 * time.Minute

// Settled reports whether nothing more will change: sending has finished and
// every receipt is in (or stopped coming), or the campaign failed.
func (p Progress) Settled(now time.Time) bool {
	switch p.Status {
	case StatusFailed:
		return true
	case StatusCompleted:
		return p.PendingReceipts == 0 || (p.CompletedAt != nil && now.Sub(*p.CompletedAt) > receiptGrace)
	}
	return false
}

package api

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"time"

	"campaign-composer/internal/events"
)

// keepAliveEvery also bounds how late a missed doorbell can delay an event.
var keepAliveEvery = 15 * time.Second

type streamOptions struct {
	// Finished is checked after each read; when it reports true the stream
	// sends "end" so the browser does not reconnect.
	Finished func(ctx context.Context) (bool, error)
	// Snapshot, if set, is sent as a "progress" event when the stream opens and
	// after doorbells, at most once per SnapshotEvery (with a trailing send, so
	// the latest state always arrives).
	Snapshot      func(ctx context.Context) (any, error)
	SnapshotEvery time.Duration
}

// streamTopic streams a topic's events with server-sent events. Ported from the
// agents-platform run stream.
//
// It first replays stored events after Last-Event-ID (sent by the browser when
// it reconnects) or ?after=, then waits for new ones. Stored and live events
// come from the same query, so nothing falls in between. Streamed text arrives
// as "delta" events, which are not stored: a JSON object as the producer wrote
// it (e.g. {"field":"sms","text":"..."}), or {"text":...} for plain text.
func (s *Server) streamTopic(w http.ResponseWriter, r *http.Request, topic string, opts streamOptions) {
	ctx := r.Context()
	after, _ := strconv.ParseInt(r.Header.Get("Last-Event-ID"), 10, 64)
	if v := r.URL.Query().Get("after"); v != "" {
		after, _ = strconv.ParseInt(v, 10, 64)
	}

	// Subscribe before the first query, so an event stored in between still
	// rings the bell.
	sub := s.hub.Subscribe(topic)
	defer s.hub.Unsubscribe(sub)

	rc := http.NewResponseController(w)
	h := w.Header()
	h.Set("Content-Type", "text/event-stream")
	h.Set("Cache-Control", "no-cache")
	h.Set("X-Accel-Buffering", "no") // tell proxies not to buffer
	w.WriteHeader(http.StatusOK)
	io.WriteString(w, "retry: 2000\n\n")
	rc.Flush()

	var (
		lastSnap  time.Time
		snapTimer <-chan time.Time
	)
	sendSnapshot := func() bool {
		snapTimer = nil
		lastSnap = time.Now()
		v, err := opts.Snapshot(ctx)
		if err != nil {
			return false
		}
		data, _ := json.Marshal(v)
		fmt.Fprintf(w, "event: progress\ndata: %s\n\n", data)
		return true
	}
	maybeSnapshot := func() {
		if opts.Snapshot == nil {
			return
		}
		every := opts.SnapshotEvery
		if wait := every - time.Since(lastSnap); wait <= 0 {
			sendSnapshot()
		} else if snapTimer == nil {
			snapTimer = time.After(wait)
		}
	}

	keepAlive := time.NewTicker(keepAliveEvery)
	defer keepAlive.Stop()
	for {
		evs, err := events.Since(ctx, s.pool, topic, after)
		if err != nil {
			return
		}
		for _, ev := range evs {
			data, _ := json.Marshal(ev)
			fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", ev.Seq, ev.Type, data)
			after = ev.Seq
		}
		maybeSnapshot()
		if opts.Finished != nil {
			if done, err := opts.Finished(ctx); err != nil || done {
				if opts.Snapshot != nil {
					sendSnapshot() // the final state, even if one was sent a moment ago
				}
				io.WriteString(w, "event: end\ndata: {}\n\n")
				rc.Flush()
				return
			}
		}
		rc.Flush()

	wait:
		for {
			select {
			case <-ctx.Done():
				return
			case <-s.closing:
				return
			case <-keepAlive.C:
				io.WriteString(w, ": keep-alive\n\n")
				rc.Flush()
				break wait // also re-reads, in case a doorbell was missed
			case <-snapTimer:
				sendSnapshot()
				rc.Flush()
			case sig := <-sub.C:
				if sig.Delta == "" {
					break wait
				}
				data := []byte(sig.Delta)
				if !json.Valid(data) || data[0] != '{' {
					data, _ = json.Marshal(map[string]string{"text": sig.Delta})
				}
				fmt.Fprintf(w, "event: delta\ndata: %s\n\n", data)
				rc.Flush()
			}
		}
	}
}

