import type { AudienceResult, Campaign, DeliveryRow, Field, Preview, Rule } from './types'

/** An error answer from the API, with its code and any listed problems. */
export class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public problems: string[] = [],
  ) {
    super(message)
  }
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  const res = await fetch(path, {
    method,
    headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  const data = await res.json().catch(() => ({}))
  if (!res.ok) {
    const e = data?.error ?? {}
    throw new ApiError(res.status, e.code ?? 'error', e.message ?? res.statusText, e.problems ?? [])
  }
  return data as T
}

export const api = {
  fields: () => request<{ fields: Field[] }>('GET', '/api/segments/fields').then((r) => r.fields),
  preview: (rule: Rule) => request<{ rule: Rule; preview: Preview }>('POST', '/api/segments/preview', { rule }),

  listCampaigns: () => request<{ campaigns: Campaign[] }>('GET', '/api/campaigns').then((r) => r.campaigns),
  getCampaign: (id: string) => request<Campaign>('GET', `/api/campaigns/${id}`),
  createCampaign: (brief: string) => request<Campaign>('POST', '/api/campaigns', { brief }),

  generateAudience: (id: string) => request<AudienceResult>('POST', `/api/campaigns/${id}/audience`),
  refineAudience: (id: string, instruction: string) =>
    request<AudienceResult>('POST', `/api/campaigns/${id}/audience/refine`, { instruction }),
  setRule: (id: string, rule: Rule) => request<AudienceResult>('PUT', `/api/campaigns/${id}/audience`, { rule }),

  generateContent: (id: string, language: string, instruction = '') =>
    request<Campaign>('POST', `/api/campaigns/${id}/content`, { language, instruction }),
  setContent: (id: string, c: { language: string; sms: string; email_subject: string; email_body: string }) =>
    request<Campaign>('PUT', `/api/campaigns/${id}/content`, c),

  approve: (id: string) => request<{ campaign: Campaign; sms: number; email: number }>('POST', `/api/campaigns/${id}/approve`),
  deliveries: (id: string, status = '', limit = 50) =>
    request<{ deliveries: DeliveryRow[] }>('GET', `/api/campaigns/${id}/deliveries?status=${status}&limit=${limit}`)
      .then((r) => r.deliveries),
}

import type { Progress } from './types'

export interface ContentDelta {
  attempt: number
  field: 'sms' | 'email_subject' | 'email_body'
  text: string
}

export interface StreamHandlers {
  /** A stored event: created, audience_ready, content_started, content_ready, approved, completed, ... */
  onEvent?: (type: string, data: unknown) => void
  /** Message text as the AI writes it. */
  onDelta?: (d: ContentDelta) => void
  /** Delivery progress, at most every 500 ms. */
  onProgress?: (p: Progress) => void
  /** The server said nothing more will change. */
  onEnd?: () => void
}

const storedEvents = [
  'created', 'audience_ready', 'content_started', 'content_ready', 'content_failed', 'approved', 'completed',
]

/**
 * Opens a campaign's event stream. EventSource reconnects by itself and sends
 * Last-Event-ID, so the server replays what was missed. Returns a close function.
 */
export function openCampaignStream(id: string, h: StreamHandlers): () => void {
  const es = new EventSource(`/api/campaigns/${id}/events`)
  for (const type of storedEvents) {
    es.addEventListener(type, (e) => {
      const ev = JSON.parse((e as MessageEvent).data)
      h.onEvent?.(type, ev.data)
    })
  }
  es.addEventListener('delta', (e) => {
    const d = JSON.parse((e as MessageEvent).data)
    if (d.field) h.onDelta?.(d as ContentDelta)
  })
  es.addEventListener('progress', (e) => h.onProgress?.(JSON.parse((e as MessageEvent).data)))
  es.addEventListener('end', () => {
    es.close()
    h.onEnd?.()
  })
  return () => es.close()
}

import type { Condition, Field, Group, Leaf, Rule } from './types'

export function isGroup(c: Condition): c is Group {
  return (c as Group).conditions !== undefined
}

const opText: Record<string, string> = {
  eq: 'is',
  neq: 'is not',
  in: 'is one of',
  not_in: 'is none of',
  gt: '>',
  gte: '≥',
  lt: '<',
  lte: '≤',
  between: 'between',
  within_days: 'in the last',
  not_within_days: 'not in the last',
  ever: 'ever',
  never: 'never',
}

/** A short human label for one condition, e.g. "Last added to cart · in the last 30 days". */
export function describeLeaf(c: Leaf, fields: Field[]): { field: string; op: string; value: string } {
  const label = fields.find((f) => f.name === c.field)?.label ?? c.field
  const op = opText[c.op] ?? c.op
  let value = ''
  switch (c.op) {
    case 'ever':
    case 'never':
      break
    case 'within_days':
    case 'not_within_days':
      value = `${c.value} days`
      break
    case 'between':
      value = (c.value as number[]).join(' – ')
      break
    case 'in':
    case 'not_in':
      value = (c.value as string[]).join(', ')
      break
    default:
      value = String(c.value)
  }
  return { field: label, op, value }
}

/** Returns a copy of the rule without the condition at path (top index, then inner index). */
export function removeCondition(rule: Rule, top: number, inner?: number): Rule {
  const conditions = rule.conditions.flatMap((c, i): Condition[] => {
    if (i !== top) return [c]
    if (inner === undefined || !isGroup(c)) return []
    const rest = c.conditions.filter((_, j) => j !== inner)
    return rest.length ? [{ ...c, conditions: rest }] : []
  })
  return { ...rule, conditions }
}

/** Returns a copy of the rule with one leaf's value replaced. */
export function setLeafValue(rule: Rule, top: number, inner: number | undefined, value: unknown): Rule {
  const conditions = rule.conditions.map((c, i): Condition => {
    if (i !== top) return c
    if (inner === undefined) return { ...(c as Leaf), value }
    const g = c as Group
    return { ...g, conditions: g.conditions.map((l, j) => (j === inner ? { ...l, value } : l)) }
  })
  return { ...rule, conditions }
}

// Mirrors internal/message for instant feedback while typing. The server's
// check is the one that counts; this only keeps the counter live.

export const SMS_MAX = 160
export const SUBJECT_MAX = 80
export const VARIABLES = ['first_name', 'last_name', 'city'] as const

export type Longest = Record<(typeof VARIABLES)[number], number>

const varRe = /\{\{\s*([^{}]*?)\s*\}\}/g

const gsmBasic =
  '@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&\'()*+,-./0123456789:;<=>?' +
  '¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà'
const gsmExtension = '^{}\\[~]|€\f'

/** Characters once personalized for the recipient with the longest values. */
export function worstCaseLength(text: string, longest: Longest): number {
  let n = [...text.replace(varRe, '')].length
  for (const m of text.matchAll(varRe)) n += longest[m[1] as keyof Longest] ?? 0
  return n
}

export function unknownVariables(text: string): string[] {
  return [...text.matchAll(varRe)].map((m) => m[1]).filter((v) => !(VARIABLES as readonly string[]).includes(v))
}

/** The encoding an SMS needs and how many parts it is sent as. */
export function smsSegments(text: string): { encoding: 'GSM-7' | 'UCS-2'; segments: number } {
  let units = 0
  for (const ch of text) {
    if (gsmBasic.includes(ch)) units++
    else if (gsmExtension.includes(ch)) units += 2
    else {
      let utf16 = 0
      for (const c of text) utf16 += c.length // code units: 2 for characters beyond the BMP
      return { encoding: 'UCS-2', segments: parts(utf16, 70, 67) }
    }
  }
  return { encoding: 'GSM-7', segments: parts(units, 160, 153) }
}

function parts(units: number, single: number, multi: number): number {
  if (units === 0) return 0
  return units <= single ? 1 : Math.ceil(units / multi)
}

export interface Recipient {
  first_name: string
  last_name: string
  city: string
}

export function render(text: string, r: Recipient): string {
  return text.replace(varRe, (whole, name: string) =>
    (VARIABLES as readonly string[]).includes(name) ? r[name as keyof Recipient] : whole,
  )
}

import { describe, expect, it } from 'vitest'
import { render, smsSegments, unknownVariables, worstCaseLength } from './sms'
import { describeLeaf, removeCondition, setLeafValue } from './rules'
import type { Field, Rule } from './types'

const longest = { first_name: 11, last_name: 9, city: 9 }

describe('sms helpers (mirror internal/message)', () => {
  it('measures the worst case after personalization', () => {
    expect(worstCaseLength('Hi {{first_name}}!', longest)).toBe(4 + 11)
    expect(worstCaseLength('Şehir: {{ city }}', longest)).toBe(7 + 9) // characters, not bytes
  })
  it('counts SMS parts like the server', () => {
    expect(smsSegments('a'.repeat(160))).toEqual({ encoding: 'GSM-7', segments: 1 })
    expect(smsSegments('a'.repeat(161))).toEqual({ encoding: 'GSM-7', segments: 2 })
    expect(smsSegments('€'.repeat(81))).toEqual({ encoding: 'GSM-7', segments: 2 })
    expect(smsSegments('ş'.repeat(70))).toEqual({ encoding: 'UCS-2', segments: 1 })
    expect(smsSegments('ş'.repeat(71))).toEqual({ encoding: 'UCS-2', segments: 2 })
    expect(smsSegments('Çok güzel üzüm')).toEqual({ encoding: 'GSM-7', segments: 1 })
  })
  it('renders and flags unknown variables', () => {
    expect(render('Merhaba {{first_name}}, {{city}}', { first_name: 'Ayşe', last_name: 'Y', city: 'İzmir' })).toBe(
      'Merhaba Ayşe, İzmir',
    )
    expect(unknownVariables('Hi {{nickname}} {{first_name}}')).toEqual(['nickname'])
  })
})

const fields: Field[] = [
  { name: 'city', label: 'City', kind: 'text', ops: ['eq'], values: ['İstanbul', 'Ankara'] },
  { name: 'last_cart_at', label: 'Last added to cart', kind: 'date', ops: ['within_days'] },
]

const rule: Rule = {
  match: 'all',
  conditions: [
    { field: 'city', op: 'eq', value: 'İstanbul' },
    { match: 'any', conditions: [{ field: 'last_cart_at', op: 'within_days', value: 30 }, { field: 'city', op: 'eq', value: 'Ankara' }] },
  ],
}

describe('rule helpers', () => {
  it('describes conditions for chips', () => {
    expect(describeLeaf({ field: 'last_cart_at', op: 'not_within_days', value: 30 }, fields)).toEqual({
      field: 'Last added to cart', op: 'not in the last', value: '30 days',
    })
    expect(describeLeaf({ field: 'last_purchase_at', op: 'never', value: null }, fields).value).toBe('')
  })
  it('removes a condition, dropping groups that become empty', () => {
    expect(removeCondition(rule, 0).conditions).toHaveLength(1)
    const one = removeCondition(rule, 1, 0)
    expect((one.conditions[1] as { conditions: unknown[] }).conditions).toHaveLength(1)
    expect(removeCondition(removeCondition(rule, 1, 0), 1, 0).conditions).toHaveLength(1)
    expect(rule.conditions).toHaveLength(2) // the original is not changed
  })
  it('sets a leaf value inside a group', () => {
    const r = setLeafValue(rule, 1, 0, 14)
    expect((r.conditions[1] as { conditions: { value: unknown }[] }).conditions[0].value).toBe(14)
  })
})

