const preview = ref<Preview | null>(null)
const progress = ref<Progress | null>(null)
const streaming = ref({ sms: '', email_subject: '', email_body: '' })
const error = ref('')
const audienceStep = ref<InstanceType<typeof AudienceStep>>()
let attempt = 0
let close: (() => void) | undefined

const approved = computed(() => campaign.value?.approved_at != null)
const locked = computed(() => approved.value)

async function reload() {
  campaign.value = await api.getCampaign(props.id)
}

async function loadPreview() {
  if (campaign.value?.rule) preview.value = (await api.preview(campaign.value.rule)).preview
}

function onAudience(r: AudienceResult) {
  campaign.value = r.campaign
  preview.value = r.preview
}

onMounted(async () => {
  try {
    ;[campaign.value, fields.value] = await Promise.all([api.getCampaign(props.id), api.fields()])
  } catch (e) {
    error.value = (e as Error).message
    return
  }
  loadPreview()
  close = openCampaignStream(props.id, {
    onEvent: (type) => {
      if (type === 'content_started') {
        attempt = 0
        streaming.value = { sms: '', email_subject: '', email_body: '' }
      }
      if (type !== 'created') reload()
    },
    onDelta: (d) => {
      if (d.attempt !== attempt) { // a repair round starts over
        attempt = d.attempt
        streaming.value = { sms: '', email_subject: '', email_body: '' }
      }
      streaming.value[d.field] += d.text
    },
    onProgress: (p) => (progress.value = p),
    onEnd: () => reload(),
  })
  // Coming from "New campaign": build the audience right away.
  if (route.query.start && campaign.value?.status === 'draft' && !campaign.value.rule) audienceStep.value?.generate()
})
