<script setup lang="ts">
// A full-width band of small squares in the delivery-status colours, dense at
// the top and dissolving towards the bottom. It drifts slowly, like messages
// going out. Generated procedurally from value noise; no images.
import { onBeforeUnmount, onMounted, ref } from 'vue'

const props = withDefaults(defineProps<{ rows?: number; cell?: number; gap?: number }>(), { rows: 26, cell: 10, gap: 2 })
const canvas = ref<HTMLCanvasElement>()
const wrap = ref<HTMLDivElement>()

// Smooth 2D value noise from a hashed lattice.
function hash(x: number, y: number): number {
  let h = (x * 374761393 + y * 668265263) | 0
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295
}
function noise(x: number, y: number): number {
  const xi = Math.floor(x), yi = Math.floor(y)
  const xf = x - xi, yf = y - yi
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf)
  const a = hash(xi, yi), b = hash(xi + 1, yi), c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1)
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
}
function fbm(x: number, y: number): number {
  return noise(x, y) * 0.6 + noise(x * 2.1, y * 2.1) * 0.3 + noise(x * 4.3, y * 4.3) * 0.1
}

let colours: Record<string, string> = {}
let frame = 0
let timer: number | undefined
let observer: ResizeObserver | undefined

function draw(t: number) {
  const el = canvas.value, box = wrap.value
  if (!el || !box) return
  const { rows, cell, gap } = props
  const step = cell + gap
  const width = box.clientWidth
  const cols = Math.ceil(width / step)
  const height = rows * step
  const dpr = window.devicePixelRatio || 1
  if (el.width !== Math.round(width * dpr)) {
    el.width = Math.round(width * dpr)
    el.height = Math.round(height * dpr)
    el.style.height = `${height}px`
  }
  const ctx = el.getContext('2d')!
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, width, height)

  for (let y = 0; y < rows; y++) {
    const depth = y / rows // 0 at the top, 1 at the bottom
    for (let x = 0; x < cols; x++) {
      // Keep a square if the noise beats a threshold that rises with depth,
      // so the band is solid at the top and breaks up into drips below.
      const density = fbm(x * 0.07 + t * 0.015, y * 0.16)
      const drip = noise(x * 0.35, 3.7) * 0.35
      if (density < 0.18 + Math.pow(depth, 1.6) * (0.95 - drip)) continue

      const tone = fbm(x * 0.035 - t * 0.01 + 40, y * 0.06 + 11)
      let c = tone < 0.42 ? colours.sent : tone < 0.56 ? colours.delivered : tone < 0.7 ? colours.sent : colours.active
      if (c === colours.active && hash(x, y + Math.floor(t / 40)) < 0.06) c = colours.failed
      ctx.fillStyle = c
      ctx.fillRect(x * step, y * step, cell, cell)
    }
  }
}

onMounted(() => {
  const css = getComputedStyle(document.documentElement)
  for (const k of ['sent', 'delivered', 'active', 'failed']) colours[k] = css.getPropertyValue(`--st-${k}`).trim()
  draw(0)
  observer = new ResizeObserver(() => draw(frame))
  observer.observe(wrap.value!)
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    timer = window.setInterval(() => {
      if (!document.hidden) draw(++frame)
    }, 120)
  }
})
onBeforeUnmount(() => {
  observer?.disconnect()
  if (timer) clearInterval(timer)
})
</script>

<template>
  <div ref="wrap" class="w-full" aria-hidden="true">
    <canvas ref="canvas" class="block w-full" />
  </div>
</template>
EOF
