<script setup lang="ts">
// The home page band. Each square is one real message this app has sent, the
// most recent ones, coloured by status. When new data arrives, a wave sweeps
// across: a square starts grey (queued), turns yellow (sending), then blue
// (sent), and settles on its real status (navy delivered, red not delivered).
// With no messages yet it shows a procedural placeholder instead.
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'

const props = withDefaults(defineProps<{ grid: string | null; maxRows?: number; cell?: number; gap?: number }>(),
  { maxRows: 14, cell: 10, gap: 2 })
const emit = defineEmits<{ shown: [count: number] }>()
const canvas = ref<HTMLCanvasElement>()
const wrap = ref<HTMLDivElement>()

const STEP_MS = 220 // time spent as "sending" and as "sent" during the wave
const reduced = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches

let colours: Record<string, string> = {}
let cols = 1
let shown = '' // the codes currently drawn, oldest first
let starts: number[] = [] // per square: when its wave starts (ms, performance.now)
let raf = 0
let placeholderTimer: number | undefined
let observer: ResizeObserver | undefined

const codeColour = (c: string) =>
  ({ q: colours.queued, s: colours.active, r: colours.active, t: colours.sent, d: colours.delivered })[c] ?? colours.failed

function layout() {
  const el = canvas.value!, box = wrap.value!
  const step = props.cell + props.gap
  const width = box.clientWidth
  cols = Math.max(1, Math.ceil(width / step))
  const rows = props.grid ? Math.min(props.maxRows, Math.ceil(Math.min(props.grid.length, cols * props.maxRows) / cols)) : props.maxRows
  const height = Math.max(1, rows) * step
  const dpr = window.devicePixelRatio || 1
  el.width = Math.round(width * dpr)
  el.height = Math.round(height * dpr)
  el.style.height = `${height}px`
  const ctx = el.getContext('2d')!
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  return { ctx, width, height, step }
}

// Starts a wave for every square whose status is new or changed.
function setData(grid: string, animate: boolean) {
  const visible = grid.slice(-cols * props.maxRows)
  const now = performance.now()
  const next: number[] = []
  for (let i = 0; i < visible.length; i++) {
    const x = i % cols, y = Math.floor(i / cols)
    const changed = shown[i] !== visible[i]
    next[i] = animate && changed && !reduced ? now + x * 16 + y * 10 : (starts[i] ?? 0)
  }
  shown = visible
  starts = next
  emit('shown', visible.length)
  cancelAnimationFrame(raf)
  raf = requestAnimationFrame(drawData)
}

function drawData() {
  const { ctx, width, height, step } = layout()
  ctx.clearRect(0, 0, width, height)
  const now = performance.now()
  let animating = false
  for (let i = 0; i < shown.length; i++) {
    const t = now - starts[i]
    let c: string
    if (t < 0) c = colours.queued
    else if (t < STEP_MS) c = colours.active
    else if (t < STEP_MS * 2) c = colours.sent
    else c = codeColour(shown[i])
    if (t < STEP_MS * 2) animating = true
    ctx.fillStyle = c
    ctx.fillRect((i % cols) * step, Math.floor(i / cols) * step, props.cell, props.cell)
  }
  if (animating) raf = requestAnimationFrame(drawData)
}

// ---- Placeholder (no messages yet): drifting value noise. ----
function hash(x: number, y: number): number {
  let h = (x * 374761393 + y * 668265263) | 0
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295
}
function noise(x: number, y: number): number {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf)
  const a = hash(xi, yi), b = hash(xi + 1, yi), c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1)
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
}
const fbm = (x: number, y: number) => noise(x, y) * 0.6 + noise(x * 2.1, y * 2.1) * 0.3 + noise(x * 4.3, y * 4.3) * 0.1
let frame = 0

function drawPlaceholder() {
  const { ctx, width, height, step } = layout()
  ctx.clearRect(0, 0, width, height)
  const rows = props.maxRows
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const density = fbm(x * 0.07 + frame * 0.015, y * 0.16)
      if (density < 0.18 + Math.pow(y / rows, 1.6) * (0.95 - noise(x * 0.35, 3.7) * 0.35)) continue
      const tone = fbm(x * 0.035 - frame * 0.01 + 40, y * 0.06 + 11)
      ctx.fillStyle = tone < 0.38 ? colours.sent : tone < 0.5 ? colours.delivered : tone < 0.6 ? colours.sent : colours.active
      ctx.fillRect(x * step, y * step, props.cell, props.cell)
    }
  }
}

function render(animate: boolean) {
