func sentSMSByLanguage(t *testing.T, env sendingEnv, rec *recorder, id string) map[string]map[string]bool {
	t.Helper()
	if status, res := call(t, "POST", env.api.URL+"/api/campaigns/"+id+"/approve", ""); status != 200 {
